INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 1, 'Visto que muitos já empreenderam pôr em ordem a narração das coisas que entre nós se cumpriram,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 2, 'como no-las referiram os que, desde o princípio, as viram, e foram ministros da palavra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 3, 'pareceu-me bom também a mim, depois de ter investigado diligentemente tudo desde o princípio, escrever-te por ordem a sua narração, excelentíssimo Teófilo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 4, 'para que conheças a solidez dos ensinamentos que recebeste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 5, 'Houve no tempo de Herodes, rei da Judeia, um sacerdote chamado Zacarias, da turma de Abias, e sua mulher era da descendência de Arão, e chamava-se Isabel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 6, 'Ambos eram justos diante de Deus, caminhando irrepreensìvelmente em todos os mandamentos e preceitos do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 7, 'Não tinham filhos, porque Isabel era estéril, e ambos se achavam em idade avançada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 8, 'Sucedeu que, exercendo Zacarias diante de Deus as funções de sacerdote na ordem da sua turma,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 9, 'segundo o costume do sacerdócio, tocou-lhe por sorte entrar no templo do Senhor a oferecer o incenso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 10, 'Toda a multidão do povo estava fazendo oração da parte de fora, à hora do incenso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 11, 'Apareceu-lhe um anjo do Senhor, posto de pé ao lado direito do altar do incenso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 12, 'Zacarias, ao vê-lo, ficou perturbado, e o temor o assaltou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 13, 'Mas o anjo disse-lhe: "Não temas, Zacarias, porque foi ouvida a tua oração; tua mulher Isabel te dará um filho, ao qual porás o nome de João.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 14, 'Será para ti motivo de gozo e de alegria, e muitos se alegrarão no seu nascimento;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 15, 'porque ele será grande diante do Senhor; não beberá vinho nem outra bebida inebriante; será cheio do Espírito Santo desde o ventre de sua mãe;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 16, 'e converterá muitos dos filhos de Israel ao Senhor seu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 17, 'Irá adiante de Deus com o espírito e a fortaleza de Elias, a fim de reconduzir os corações dos pais para os filhos (Ml. 4, 5-6), e os rebeldes à prudência dos justos, para preparar ao Senhor um povo bem disposto."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 18, 'Zacarias disse ao anjo: "Como conhecerei isso? Porque eu sou velho, e minha mulher está avançada em anos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 19, 'O anjo respondeu-lhe: "Eu sou Gabriel, que assisto diante de Deus; fui enviado para te falar e te dar esta boa nova.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 20, 'Eis que ficarás mudo, e não poderás falar até ao dia em que estas coisas sucedam, visto que não acreditaste nas minhas palavras, que se hão-de cumprir a seu tempo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 21, 'Entretanto o povo estava esperando Zacarias, e admirava-se de ver que ele se demorava tanto tempo no templo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 22, 'Quando saiu, não lhes podia falar, e compreenderam que tinha tido no templo alguma visão, o que lhes dava a entender por acenos; e ficou mudo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 23, 'Aconteceu que, depois de terem acabado os dias do seu ministério, retirou-se para sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 24, 'Alguns dias depois, Isabel, sua mulher, concebeu, e durante cinco meses esteve escondida, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 25, '"Isto é uma graça que me fez o Senhor nos dias em que me olhou para tirar o meu opróbrio de entre os homens." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 26, 'Estando Isabel no sexto mês, foi enviado por Deus o anjo Gabriel a uma cidade da Galileia, chamada Nazaré,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 27, 'a uma virgem desposada com um varão, chamado José, da casa de David; o nome da virgem era Maria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 28, 'Entrando o anjo onde ela estava, disse-Ihe: "Deus te salve, cheia de graça; o Senhor é contigo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 29, 'Ela, ao ouvir estas palavras, perturbou-se, e discorria pensativa que saudação seria esta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 30, 'O anjo disse-lhe: "Não temas, Maria, pois achaste graça diante de Deus;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 31, 'eis que conceberás no teu ventre, e darás à luz um filho, a quem porás o nome de Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 32, 'Será grande, será chamado Filho do Altíssimo, e o Senhor Deus lhe dará o trono de seu pai David; reinará sobre a casa de Jacob eternamente,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 33, 'e o seu reino não terá fim."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 34, 'Maria disse ao anjo: "Como se fará isso, pois eu não conheço varão?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 35, 'O anjo respondeu-lhe: "O Espírito Santo descerá sobre ti, e a virtude do Altíssimo te cobrirá com a sua sombra; por isso mesmo o Menino que há-de nascer de ti, será santo e será chamado Filho de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 36, 'Eis que também Isabel, tua parenta, concebeu um filho na sua velhice; e este é o sexto mês da que se dizia estéril;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 37, 'porque a Deus nada é impossível."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 38, 'Então Maria disse: "Eis aqui a serva do Senhor, faça-se em mim a tua palavra." E o anjo afastou-se dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 39, 'Naqueles dias, levantando-se Maria, foi com pressa às montanhas, a uma cidade de Judá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 40, 'Entrou em casa de Zacarias, e saudou Isabel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 41, 'Aconteceu que, apenas Isabel ouviu a saudação de Maria, o menino saltou no seu ventre, e Isabel ficou cheia do Espírito Santo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 42, 'e exclamou em alta voz: "Bendita és tu entre todas as mulheres, e bendito é o fruto do teu ventre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 43, 'Donde a mim esta dita, que a mãe do meu Senhor venha ter comigo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 44, 'Porque, logo que a voz da tua saudação chegou aos meus ouvidos, o menino saltou de alegria no meu ventre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 45, 'Bem-aventurada a que acreditou, porque se hão-de cumprir as coisas que da parte do Senhor foram ditas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 46, 'Então Maria disse : "A minha alma glorifica o Senhor; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 47, 'e o meu espírito exulta em Deus meu Salvador,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 48, 'porque lançou os olhos para a baixeza da sua serva. Portanto, eis que, de hoje em diante, todas as gerações me chamarão bem-aventurada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 49, 'Porque o Todo-poderoso fez em mim grandes coisas, o seu nome é santo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 50, 'E a sua misericórdia se estende de geração em geração sobre aqueles que o temem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 51, 'Manifestou o poder do seu braço, dispersou os homens de coração soberbo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 52, 'Depôs do trono os poderosos, e elevou os humildes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 53, 'Encheu de bens os famintos, e despediu vazios os ricos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 54, 'Tomou cuidado de Israel, seu servo, lembrado da sua misericórdia;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 55, 'Conforme tinha prometido a nossos pais, a Abraão e à sua posteridade para sempre."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 56, 'Maria ficou com Isabel cerca de três meses; depois voltou para sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 57, 'Completou-se para Isabel o tempo de dar à luz, e deu à luz um filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 58, 'Os seus vizinhos e parentes ouviram dizer que o Senhor tinha assinalado com ela a sua misericórdia, e congratulavam-se com ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 59, 'Aconteceu que, ao oitavo dia, foram circuncidar o menino, e chamavam-lhe Zacarias do nome de seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 60, 'Porém, interveio sua mãe, e disse: "De nenhuma sorte, mas será chamado João."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 61, 'Disseram-lhe; "Ninguém há na tua parentela que tenha este nome."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 62, 'E perguntavam por acenos ao pai do menino como queria que se chamasse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 63, 'Ele, pedindo uma tabuinha, escreveu assim: "O seu nome é João." Todos ficaram admirados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 64, 'E logo se abriu a sua boca, a sua língua se desprendeu, e falava, bendizendo a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 65, 'O temor se apoderou de todos os seus vizinhos, e divulgaram-se todas estas maravilhas por todas as montanhas da Judeia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 66, 'Todos os que as ouviram, as ponderavam no seu coração, dizendo: "Quem virá a ser este menino?" Porque a mão do Senhor era com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 67, 'Zacarias, seu pai, foi cheio do Espírito Santo, e profetizou, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 68, '"Bendito seja o Senhor, Deus de Israel, porque visitou e resgatou o seu povo; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 69, 'e suscitou uma força para nos salvar, na casa de seu servo David, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 70, 'conforme anunciou pela boca dos seus santos, de seus profetas, desde os tempos antigos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 71, 'que nos livraria de nossos inimigos, e das mãos de todos os que nos odeiam;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 72, 'para exercer a sua misericórdia a favor de nossos pais, e lembrar-se da sua santa aliança, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 73, 'segundo o juramento que fez a nosso pai Abraão, de nos conceder'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 74, 'que, livres das mãos dos nossos inimigos, o sirvamos sem temor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 75, '(andando) diante dele com santidade e justiça, durante todos os dias da nossa vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 76, 'E tu, menino, serás chamado o profeta do Altíssimo, porque irás adiante da face do Senhor, a preparar os seus caminhos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 77, 'para dar ao seu povo o conhecimento da salvação, pela remissão dos seus pecados,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 78, 'graças à terna misericórdia do nosso Deus, que nos trará do alto a visita do sol nascente, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 79, 'para alumiar os que jazem nas trevas e na sombra da morte; para dirigir os nossos pés no caminho da paz."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 80, 'Ora o menino crescia e se fortificava no espírito. E habitou nos desertos até ao dia da sua manifestação a Israel.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 1, 'Naqueles dias, saiu um édito de César Augusto, prescrevendo o recenseamento de todo o mundo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 2, 'Este recenseamento foi anterior ao que se realizou quando Quirino era governador da Síria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 3, 'Iam todos recensear-se, cada um à sua cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 4, 'José foi também da Galileia, da cidade de Nazaré, à Judeia, à cidade de David, que se chamava Belém, porque era da casa e família de David,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 5, 'para se recensear juntamente com Maria, sua esposa, que estava grávida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 6, 'Ora, estando ali, aconteceu completarem-se os dias em que devia dar à luz,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 7, 'e deu à luz o seu filho primogénito, e o enfaixou, e o reclinou numa manjedoura, porque não havia lugar para eles na estalagem. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 8, 'Naquela mesma região, havia uns pastores que velavam e faziam de noite a guarda ao seu rebanho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 9, 'Apareceu-lhes um anjo do Senhor, e a glória do Senhor os envolveu com a sua luz, e tiveram grande temor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 10, 'Porém o anjo disse-lhes: "Não temais, porque eis que vos anuncio uma boa nova, que será de grande alegria para todo o povo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 11, 'Nasceu-vos hoje na cidade de David um Salvador, que é o Cristo, o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 12, 'Eis o que vos servirá de sinal: Encontrareis um Menino envolto em panos, e deitado numa manjedoura."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 13, 'E subitamente apareceu com o anjo uma multidão da milícia celeste, louvando a Deus, e dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 14, '"Glória a Deus no mais alto dos céus, e paz na terra aos homens, objecto da boa vontade (de Deus)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 15, 'Depois que os anjos se retiraram deles para o céu, os pastores diziam entre si: "Vamos até Belém, e vejamos o que é que lá sucedeu, e o que é que o Senhor nos manifestou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 16, 'Foram a toda a pressa, e encontraram Maria, José, e o Menino deitado na manjedoura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 17, 'Vendo isto, conheceram o que lhes tinha sido dito acerca deste Menino.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 18, 'E todos os que ouviram, se admiraram das coisas que lhes diziam os pastores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 19, 'Maria conservava todas estas coisas, meditando-as no seu coração,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 20, 'Os pastores voltaram, glorificando e louvando a Deus por tudo o que tinham ouvido e visto, conforme lhes tinha sido dito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 21, 'Depois que se completaram os oito dias para ser circuncidado o Menino, foi-lhe posto o nome de Jesus, como lhe tinha chamado o anjo, antes que fosse concebido no ventre materno.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 22, 'Depois que se completaram os dias da purificação de Maria, segundo a lei de Moisés, levaram-no a Jerusalém para o apresentar ao Senhor Lv. 12, 6,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 23, 'segundo o que está escrito na lei do Senhor : Todo o varão primogênito será consagrado ao Senhor (Ex. 13, 2 ; Ex. 12, 15),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 24, 'e para oferecerem em sacrifício, conforme o que também está escrito na lei do Senhor, um par de rolas ou dois pombinhos (Lv. 12, 8 ; Lv. 5, 11).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 25, 'Havia então em Jerusalém um homem chamado Simeão. Este homem era justo e piedoso; esperava a consolação de Israel, e o Espírito Santo estava nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 26, 'Tinha-lhe sido revelado pelo Espírito Santo que não veria a morte, sem ver primeiro o Cristo do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 27, 'Foi ao templo conduzido pelo Espírito (de Deus). E, levando os pais o Menino Jesus, para cumprirem as prescrições usuais da lei a seu respeito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 28, 'ele o tomou em seus braços, e louvou a Deus, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 29, '"Agora, Senhor, podes deixar partir o teu servo em paz, segundo a tua palavra;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 30, 'porque os meus olhos viram a tua salvação,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 31, 'a qual preparaste em favor de todos os povos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 32, 'luz para iluminar as nações, e glória de Israel, teu povo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 33, 'Seu pai e sua mãe estavam admirados das coisas que dele se diziam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 34, 'Simeão os abençoou, e disse a Maria, sua mãe : "Eis que este Menino está posto para ruína e ressurgimento de muitos em Israel, e para ser alvo de contradição. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 35, 'E uma espada trespassará a tua alma! Assim se descobrirão os pensamentos escondidos nos corações de muitos." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 36, 'Havia também uma profetiza, chamada Ana, filha de Fanuel, da tribo de Aser. Estava em idade muito avançada. Tinha vivido sete anos com seu marido, desde a sua virgindade,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 37, 'e tinha permanecido viúva até aos oitenta e quatro anos, e não se afastava do templo, servindo a Deus noite e dia com jejuns e orações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 38, 'Ela também, sobrevindo nesta mesma ocasião, louvava a Deus, e falava de Jesus a todos os de Jerusalém que esperavam a redenção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 39, 'Depois que cumpriram tudo, segundo o que mandava a lei do Senhor, voltaram para a Galileia, para a sua cidade de Nazaré.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 40, 'O Menino crescia e se fortificava cheio de sabedoria, e a graça de Deus era com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 41, 'Seus pais iam todos os anos a Jerusalém, pela festa da Páscoa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 42, 'Quando chegou aos doze anos, indo eles a Jerusalém segundo o costume daquela festa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 43, 'acabados os dias que ela durava, quando voltaram, ficou o Menino Jesus em Jerusalém, sem que seus país o advertissem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 44, 'Julgando que ele fosse na comitiva, caminharam uma jornada, e depois procuraram-no entre os parentes e conhecidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 45, 'Não o encontrando, voltaram a Jerusalém em busca dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 46, 'Aconteceu que, três dias depois, o encontraram no templo sentado no meio dos doutores, ouvindo-os e interrogando-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 47, 'E todos os que ouviam, estavam maravilhados da sua sabedoria e das suas respostas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 48, 'Quando o viram, admiraram-se. E sua mãe disse-lhe: "Filho, porque procedeste assim connosco? Eis que teu pai e eu te procurávamos cheios de aflição."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 49, 'Ele disse-Ihes: "Para que me buscáveis? Não sabíeis que devo ocupar-me nas coisas de meu Pai?" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 50, 'Eles porém não entenderam o que lhes disse. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 51, 'Depois desceu com eles, e foi a Nazaré; e era-lhes submisso, Sua mãe conservava todas estas coisas no seu coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 52, 'Jesus crescia em sabedoria, em estatura e em graça diante de Deus e dos homens.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 1, 'No ano décimo quinto do império de Tibério César, sendo Pôncio Pilatos governador da Judeia, Herodes tetrarca da Galileia, Filipe, seu irmão, tetrarca da Itureia e da província da Traconítida, Lisânias tetrarca da Abilina.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 2, 'sendo pontífices Anás e Caifás, o Senhor falou a João, filho de Zacarias, no deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 3, 'E ele foi por toda a terra do Jordão, pregando o baptismo de penitência para remissão dos pecados,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 4, 'como está escrito no livro das palavras do profeta (Is. 40, 3-5): Voz do que clama no deserto; Preparai o caminho do Senhor, endireitai as suas veredas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 5, 'toda o vale será terraplanado, todo o monte e colina serão arrasados, os caminhos tortuosos tornar-se-ão direitos, os escabrosos planos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 6, 'e todo o homem verá a salvação de Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 7, 'Dizia pois (João) às multidões, que vinham para ser por ele baptizadas: "Raça de víboras, quem vos ensinou a fugir da ira que vos ameaça?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 8, 'Fazei, portanto, frutos dignos de penitência, e não comeceis a dizer: Temos Abraão por pai. Porque eu vos digo que Deus é poderoso para suscitar destas pedras filhos de Abraão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 9, 'Porque o machado já está posto à raiz das árvores. Toda a árvore que não dá bom fruto, será cortada e lançada no fogo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 10, 'As multidões interrogavam-no, dizendo: "Que devemos pois nós fazer?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 11, 'Respondendo, dizia-lhes: "O que tem duas túnicas, dê uma ao que não tem; e o que tem que comer, faça o mesmo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 12, 'Foram também publicanos, para serem baptizados, e disseram-lhe: "Mestre, que devemos nós fazer?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 13, 'Ele respondeu-lhes: "Não exijais nada além do que vos está fixado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 14, 'Interrogavam-no também os soldados: "E nós que faremos?" Respondeu-lhes: "Não façais violência a ninguém, nem denuncieis falsamente, e contentai-vos com o vosso soldo." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 15, 'Estando o povo na espectativa, e pensando todos nos seus corações que talvez João fosse o Cristo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 16, 'João respondeu, dizendo a todos; "Eu na verdade baptizo-vos em água, mas virá um mais forte do que eu, a quem não sou digno de desatar a correia dos seus sapatos; ele vos baptizará no Espírito Santo e no fogo; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 17, 'tomará na sua mão a pá, limpará a sua eira, e recolherá o trigo no seu celeiro, mas a palha queimá-la-à num fogo inextinguível." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 18, 'Por muitas outras exortações anunciava ao povo a boa nova.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 19, 'Porém, Herodes tetrarca, sendo repreendido por ele por causa de Herodíades, mulher de seu irmão, e por causa de todos os males que tinha feito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 20, 'acrescentou a todos os outros crimes também este: Mandar meter João num cárcere.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 21, 'Ora aconteceu que, recebendo o baptismo todo o povo, baptizado também Jesus, e estando em oração, abriu-se o céu,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 22, 'e desceu sobre ele o Espírito Santo em forma corpórea como uma pomba. E ouviu-se do céu esta voz: "Tu és o meu Filho dílecto; em ti pus as minhas complacências."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 23, 'Jesus, quando começou o seu ministério, tinha cerca de trinta anos, filho, como se julgava, de José, filho de Heli, filho de Matat,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 24, 'filho de Levi, filho de Melqui, filho de Jane, filho de José,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 25, 'filho de Matatias, filho de Amós, filho de Naum, filho de Hesli, filho de Nagé,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 26, 'filho de Maat, filho de Matalías, filho de Semei, filho de José, filho de Judá,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 27, 'filho de Joanan, filho de Resa, filho de Zorobabel, filho de Salatiel, filho de Neri,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 28, 'filho de Melqui, filho de Adi, filho de Cosam, filho de Elmadam, filho de Her,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 29, 'filho de Jesus, filho de Eliezer, filho de Jorim, filho de Matat, filho de Levi,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 30, 'filho de Simeão, filho de Judá, filho de José, filho de Joanan, filho de Eliaquim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 31, 'filho de Meléa, filho de Mena, filho de Matata, filho de Natan, filho de David,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 32, 'filho de Jessé, filho de Obed, filho de Booz, filho de Salmon, filho de Naaason,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 33, 'filho de Aminadab, filho de Arão, filho de Esron, filho de Farés, filho de Judá,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 34, 'filho de Jacob, filho de Isaac, filho de Abraão, filho de Taré, filho de Nacor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 35, 'filho de Sarag, filho de Ragau, filho de Faleg, filho de Heber, filho de Sale,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 36, 'filho de Cainan, filho de Arfasad, filho de Sem, filho de Noé, filho de Lamech,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 37, 'filho de Matusalem, filho de Heuocb, filho de Jared, filho de Malaleel, filho de Cainan,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 38, 'filho de Henós, filho de Set, filho de Adão, filho de Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 1, 'Jesus, cheio do Espirito Santo, partiu do Jordão, e foi conduzido pelo Espírito ao deserto,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 2, 'onde esteve quarenta dias, e foi tentado pelo demônio. Não comeu nada nestes dias; passados eles, teve fome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 3, 'Então o demônio disse-lhe: "Se és filho de Deus, diz a esta pedra que se converta em pão."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 4, 'Jesus respondeu-lhe: "Está escrito: O homem não vive só de pão (Dt. 8, 3)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 5, 'O demônio conduziu-o então a um alto monte, mostrou-lhe, num momento, todos os reinos da terra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 6, 'e disse-lhe: "Dar-te-ei o poder de tudo isto, e a glória destes reinos, porque eles foram-me dados, e eu dou-os a quem me parece.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 7, 'Portanto, se tu me adorares, todos eles serão teus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 8, 'Jesus, respondeu-Ihe: "Está escrito: Adorarás o Senhor teu Deus, e a ele só servirás (Dt. 6, 13)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 9, 'Levou-o também a Jerusalém, pô-lo sobre o pináculo do templo, e disse-lhe: "Se és filho de Deus, lança-te daqui abaixo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 10, 'porque está escrito que Deus mandou aos seus anjos que te guardem,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 11, 'e que te sustenham em suas mãos, para não magoares ó teu pé em nenhuma pedra (Ps. 90, 11-12)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 12, 'Jesus, respondeu-lhe: "Também foi dito: Não tentarás o Senhor teu Deus (Dt. 6, 16)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 13, 'Terminada toda a tentação, retirou-se dele o demônio até outra ocasião.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 14, 'Jesus voltou sob o impulso do Espírito para a Galileia, e a sua fama divulgou-se por toda a região.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 15, 'Ensinava nas sinagogas, e era aclamado por todos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 16, 'Foi a Nazaré, onde se tinha criado, entrou na sinagoga, segundo o seu costume, em dia de sábado, e levantou-se para fazer a leitura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 17, 'Foi-lhe dado o livro do profeta Isaías. Quando desenrolou o livro, encontrou o lugar onde estava escrito (Is. 61, 1-2; Is. 58, 6):'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 18, 'O Espírito do Senhor repousou sobre mim; pelo que me ungiu para anunciar a boa nova aos pobres; me enviou a sarar os contritos do coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 19, 'a anunciar aos cativos a redenção, e aos cegos a recuperação da vista, a pôr em liberdade os oprimidos, a pregar o ano favorável do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 20, 'Tendo enrolado o livro, deu-o ao ministro, e sentou-se. Estavam fixos nele os olhos de todos os que se encontravam na sinagoga.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 21, 'Começou a dizer-lhes: "Hoje cumpriu-se esta escritura que acabais de ouvir."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 22, 'E todos lhe davam testemunho, e admiravam-se das palavras de graça que saiam da sua boca, e diziam: "Não é este o filho de José?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 23, 'Então disse-lhes: "Sem dúvida que vós me aplicareis este provérbio: Médico, cura-te a ti mesmo. Todas aquelas grandes coisas que ouvimos dizer que fizeste em Cafarnaum, faze-as também aqui na tua pátria."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 24, 'Depois acrescentou : "Na verdade vos digo que nenhum profeta é bem recebido na sua pátria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 25, 'Na verdade vos digo que muitas viúvas havia em Israel no tempo de Elias, quando foi fechado o céu durante três anos e seis meses, e houve uma grande fome por toda a terra;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 26, 'e a nenhuma delas foi mandado Elias, senão a uma mulher viúva de Sarepta, do território de Sidónia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 27, 'Muitos leprosos havia em Israel no tempo do profeta Eliseu; e nenhum deles foi curado (pelo profeta), senão Naaman Sírio."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 28, 'Todos os que estavam na sinagoga, ouvindo isto, encheram-se de ira.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 29, 'Levantaram-se, lançaram-no fora da cidade, e conduziram-no até ao cume do monte, sobre o qual estava edificada a sua cidade, para o precipitarem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 30, 'Mas ele, passando pelo meio deles, retirou-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 31, 'Foi a Cafarnaum, cidade da Galileia, e ali ensinava aos sábados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 32, 'Espantavam-se da sua doutrina, porque falava com autoridade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 33, 'Estava na sinanoga um homem possesso de um demônio imundo, o qual exclamou em alta voz'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 34, '"Deixa-nos! Que tens tu que ver connosco, ó Jesus Nazareno? Vieste para nos perder? Sei quem és: o Santo de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 35, 'Jesus o repreendeu, dizendo: "Cala-te, e sai desse homem." E o demônio, depois de o ter lançado por terra no meio de todos, saiu dele, sem lhe fazer nenhum mal,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 36, 'Todos se atemorizaram, e falavam uns com os outros, dizendo: "Que é isto, ele manda com autoridade e poder aos espíritos imundos, e estes saem?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 37, 'E a sua fama ia-se espalhando por todos os lugares da região.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 38, 'Saindo Jesus da sinagoga, entrou em casa de Simão. Ora a sogra de Simão estava com febre muito alta. Pediram-lhe por ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 39, 'Ele, inclinando-se para ela, ordenou à febre, e a febre deixou-a. Ela, levantando-se logo, servia-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 40, 'Quando foi sol-posto, todos os que tinham enfermos de diversas moléstias, traziam-lhos. E ele, impondo as mãos sobre cada um, sarava-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 41, 'De muitos saíam os demônios, gritando: "Tu és o Filho de Deus." Mas ele repreendia-os severamente e impunha-lhes silêncio, porque sabiam que ele era o Cristo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 42, 'Quando se fez dia, tendo saído, foi para um lugar deserto. As multidões puseram-se a procurá-lo, e, tendo-o encontrado, detinham-no, para que se não afastasse deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 43, 'Mas ele disse-lhes: "É necessário que eu anuncie também às outras cidades a boa nova do reino de Deus, pois para isso é que fui enviado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 44, 'E andava pregando nas sinagogas da Judeia. (ver nota)');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 1, 'Um dia, comprimindo-se as multidões em volta dele para ouvir a palavra de Deus, Jesus estava junto do lago de Genesaré.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 2, 'Viu duas barcas que estacionavam à borda do lago; os pescadores tinham saído, e lavavam as redes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 3, 'Entrando numa destas barcas, que era a de Simão, rogou-lhe que se afastasse um pouco da terra. Depois, estando sentado, ensinava o povo da barca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 4, 'Quando acabou de falar, disse a Simão: "Faz-te ao largo, e lançai as vossas redes para pescar."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 5, 'Respondeu Simão: "Mestre, tendo trabalhado toda a noite, não apanhamos nada; porém, sobre a tua palavra, lançarei a rede."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 6, 'Tendo feito isto, apanharam tão grande quantidade de peixes, que a sua rede rompia-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 7, 'Então fizeram sinal aos companheiros, que estavam na outra barca, para que os viessem ajudar. Vieram, e encheram tanto ambas as barcas, que quase se afundavam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 8, 'Simão Pedro, vendo isto, lançou-se aos pés de Jesus, dizendo: "Retira-te de mim, Senhor, pois eu sou um homem pecador"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 9, 'Porque tanto ele como todos os que se encontravam com ele ficaram possuídos de espanto, por causa da pesca que tinham feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 10, 'O mesmo tinha acontecido a Tiago e a João, filhos de Zebedeu, que eram companheiros de Simão. Jesus disse a Simão: "Não tenhas medo; desta hora em diante serás pescador de homens."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 11, 'Trazidas as barcas para terra, deixando tudo, seguiram-no.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 12, 'Sucedeu que, encontrando-se Jesus numa cidade, apareceu um homem cheio de lepra, o qual, vendo Jesus, prostrou-se com o rosto por terra e suplicou-Ihe: "Senhor, se tu queres, podes limpar-me."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 13, 'Ele, estendendo a mão, tocou-o, dizendo: "Quero, sê limpo." Imediatamente desapareceu dele a lepra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 14, 'Jesus ordenou-lhe que a ninguém o dissesse. Mas vai, disse-lhe, mostra-te ao sacerdote, e oferece pela tua cura o que foi ordenado por Moisés, para lhes servir de testemunho."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 15, 'Entretanto dilatava-se cada vez mais a fama do seu nome; e concorriam muitas multidões para o ouvir e ser curadas das suas doenças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 16, 'Mas ele retirava-se para lugares desertos, e fazia oração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 17, 'Um dia, enquanto ensinava, estavam ali sentados fariseus e doutores da lei, vindos de todas as aldeias da Galileia, da Judeia e de Jerusalém; e o poder do Senhor fazia-lhe operar curas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 18, 'E eis que uns homens, levando sobre um leito um homem que estava paralítico, procuravam introduzi-lo dentro da casa, e pô-lo diante dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 19, 'Porém, não encontrando por onde o introduzir por causa da multidão, subiram ao telhado e, levantando as telhas, desceram-no com o seu leito no meio de todos diante de Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 20, 'Vendo a sua fé, Jesus disse: "Ó homem, são-te perdoados os teus pecados!" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 21, 'Então começaram os escribas e os fariseus a pensar e a dizer: "Quem é este que diz blasfêmias? Quem pode perdoar pecados, senão só Deus?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 22, 'Jesus, conhecendo os seus pensamentos, respondeu-lhes: "Que estais vós a pensar nos vossos corações?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 23, 'Que coisa é menos difícil dizer: São-te perdoados os pecados, ou dizer: Levanta-te e caminha?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 24, 'Pois, para que saibais que o Filho do homem tem poder sobre a terra de perdoar pecados, eu te ordeno, levanta-te, toma o teu leito e vai para tua casa."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 25, 'Levantando-se logo em presença deles, tomou o leito em que jazia, e foi para sua casa, glorificando a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 26, 'Ficaram todos estupefactos, e glorificavam a Deus. Possuídos de temor, diziam : "Hoje vimos coisas maravilhosas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 27, 'Depois disto, Jesus saiu, e viu sentado ao telónio um publicano, chamado Levi, e disse-lhe: "Segue-me."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 28, 'Ele, deixando tudo, levantou-se, e o seguiu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 29, 'E Levi ofereceu-lhe um grande banquete em sua casa, onde concorreu grande número de publicanos e doutros, que estavam à mesa com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 30, 'Os fariseus e os seus escribas murmuravam, dizendo aos discípulos de Jesus: "Porque comeis e bebeis vós com os publicanos e com os pecadores?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 31, 'Jesus respondeu-lhes: "Os sãos não têm necessidade de médico, mas sim os enfermos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 32, 'Não vim chamar os justos, mas os pecadores à penitência."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 33, 'Eles disseram-lhe: "Os discípulos de João, e os dos fariseus, jejuam muitas vezes e fazem orações, e os teus comem e bebem..."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 34, 'Jesus respondeu-lhes: "Porventura podeis vós fazer jejuar os amigos do esposo, enquanto o esposo está com eles?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 35, 'Mas virão dias em que lhes será tirado o esposo; então jejuarão nesses dias."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 36, 'Também lhes disse esta comparação: "Ninguém deita um retalho de vestido novo em vestido velho; doutro modo o novo rompe o velho, e o retalho do novo não condiz com o velho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 37, 'Também ninguém deita vinho novo em odres velhos; doutro modo o vinho novo fará rebentar os odres, e derramar-se-á o vinho, e perder-se-ão os odres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 38, 'Mas o vinho novo deve deitar-se em odres novos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 39, 'Ninguém depois de ter bebido vinho velho, quer do novo, porque diz: O velho é melhor."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 1, 'Num sábado, passando Jesus pelas searas, os seus discípulos colhiam espigas, e, machucando-as nas mãos, as comiam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 2, 'Alguns dos fariseus disseram-Ihes: "Porque fazeis o que não é permitido nos sábados?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 3, 'Jesus respondeu-lhes: "Não leste o que fez David, quando teve fome, ele e os que com ele estavam?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 4, 'Como entrou na casa de Deus, tomou os pães da proposição, comeu deles, e deu aos seus companheiros, embora não fosse permitido comer deles senão aos sacerdotes?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 5, 'Depois acrescentou: "O Filho do homem é Senhor também do sábado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 6, 'Aconteceu que, em outro sábado, entrou Jesus na sinagoga, e ensinava. Estava ali um homem que tinha a mão direita seca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 7, 'Os escribas e os fariseus o estavam observando para ver se curava ao sábado, a fim de terem de que o acusar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 8, 'Mas ele conhecia os seus pensamentos, e disse ao homem que tinha a mão seca: "Levanta-te, e põe-te em pé no meio." Ele, levantando-se, pôs-se de pé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 9, 'Jesus disse-lhe: "Pergunto-vos se é lícito aos sábados fazer bem ou mal, salvar a vida ou tirá-la."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 10, 'Depois, correndo a todos com o olhar, disse ao homem : "Estende a tua mão." Ele estendeu-a, e a sua mão tornou-se sã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 11, 'Eles encheram-se de furor, e falavam uns com os outros para ver que fariam contra Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 12, 'Naqueles dias Jesus retirou-se para o monte a orar, e passou toda a noite em oração a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 13, 'Quando se fez dia, chamou os seus discipulos, e escolheu doze dentre eles, aos quais deu o nome de Apóstolos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 14, 'Simão, a quem deu o sobrenome de Pedro, André, seu irmão, Tiago, João, Filipe, Bartolomeu,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 15, 'Mateus, Tomé, Tiago, filho de Alfeu, Simão, chamado o Zelador,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 16, 'Judas, irmão de Tiago, e Judas Escariotes, que foi o traidor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 17, 'Descendo com eles, parou numa planície. Estava lá um grande número dos seus discipulos, e uma grande multidão de povo de toda a Judeia, de Jerusalém, do litoral de Tiro e de Sidónia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 18, 'que tinham vindo para o ouvir, e para ser curados das suas doenças. Os que eram vexados pelos espíritos imundos ficavam também sãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 19, 'Todo o povo procurava tocá-lo, porque saía dele uma virtude que os curava a todos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 20, 'Levantando os olhos para os seus discípulos, dizia: "Bem-aventurados vós os pobres, porque vosso é o reino de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 21, 'Bem-aventurados os que agora tendes fome, porque sereis saciados. Bem-aventurados os que agora chorais, porque rireis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 22, 'Bem-aventurados sereis quando os homens vos odiarem, vos repelirem, vos carregarem de injúrias, e rejeitarem o vosso nome como mau, por causa do Filho do homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 23, 'Alegrai-vos nesse dia, e exultai, porque será grande a vossa recompensa no céu. Era assim que os pais deles tratavam os profetas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 24, 'Mas, ai de vós, ó ricos! porque tendes a vossa consolação (neste mundo). (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 25, 'Ai de vós os que estais saciados! porque vireis a ter fome. Ai de vós os que agora rides! porque gemereis e chorareis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 26, 'Ai de vós, quando todos os homens vos louvarem! porque assim faziam aos falsos profetas os pais deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 27, 'Mas digo-vos a vós, que me ouvis: Amai os vossos inimigos, fazei bem aos que vos odeiam'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 28, 'abençoai os que vos amaldiçoam, orai pelos que vos caluniam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 29, 'Ao que te ferir numa face, oferece-lhe também a outra. Ao que te tirar o manto, não o impeças de levar também a túnica. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 30, 'Dá a todo aquele que te pede: e ao que leva o que é teu, não lho tornes a pedir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 31, 'O que quereis que vos façam os homens, fazei-o vós também a eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 32, 'Se vós amais os que vos amam, que mérito tendes? Porque os pecadores também amam quem os ama.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 33, 'Se fizerdes bem aos que vos fazem bem, que mérito tendes? Os pecadores também fazem isto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 34, 'Se emprestardes àqueles de quem esperais receber, que mérito tendes? Os pecadores também emprestam aos pecadores, para que se lhes faça outro tanto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 35, 'Vós, porém, amai os vossos inimigos; fazei bem e emprestai, sem daí esperardes nada; e será grande a vossa recompensa, e sereis filhos do Altíssimo, que é bom para os ingratos e para os maus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 36, 'Sede misericordiosos, como também vosso Pai é misericordioso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 37, 'Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; perdoai, e sereis perdoados;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 38, 'dai, e dar-se-vos-à. Uma medida boa, cheia, recalcada e acogulada, vos será lançada nas dobras do vosso vestido. Porque, com a mesma medida com que medirdes para os outros, será medido para vós."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 39, 'Dizia-lhes também esta comparação : "Pode porventura um cego guiar outro cego? Não cairão ambos no barranco?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 40, 'O discípulo não é mais que o mestre; mas todo o discipulo será perfeito, se for como seu mestre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 41, 'Porque vês tu a aresta no olho do teu irmão, e não notas a trave que tens no teu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 42, 'Ou como podes tu dizer a teu irmão : Deixa, irmão, que eu tire do teu olho a aresta, não vendo tu mesmo a trave que tens no teu? Hipócrita, tira primeiro a trave do teu olho, e depois verás para tirar a aresta do olho de teu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 43, 'Porque não é boa árvore a que dá frutos maus, nem má árvore a que dá bom fruto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 44, 'Porquanto cada árvore se conhece pelo seu fruto; pois nem se colhem figos dos espinheiros, nem se vindimam uvas de um abrolho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 45, 'O homem bom, do bom tesouro do seu coração tira o bem; o homem mau, do mau tesouro tira o mal; porque a boca fala da abundância do coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 46, 'Porque me chamais vós Senhor, Senhor, e não fazeis o que eu vos digo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 47, 'Todo o que vem a mim, que ouve as minhas palavras, e as põe em prática, vou mostrar-vos a quem ele é semelhante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 48, 'É semelhante a um homem que, edificando uma casa, cavou profundamente, e pôs os alicerces sobre a rocha. Vindo uma inundação, investiu a torrente contra aquela casa, e não pôde movê-la, porque estava bem edificada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 49, 'Mas o que ouve, e não pratica, é semelhante a um homem, que edificou a sua casa sobre a terra sem fundamentos. Investiu a torrente contra ela, e logo caiu, e foi grande a ruína daquela casa."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 1, 'Tendo terminado este discurso ao povo, entrou em Cafarnaum.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 2, 'Ora um centurião tinha doente, quase a morrer, um servo que lhe era muito querido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 3, 'Tendo ouvido falar de Jesus, enviou-lhe alguns anciães dos Judeus a pedir-lhe que viesse curar o seu servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 4, 'Eles, tendo ido ter com Jesus, pediam-lhe instantemente, dizendo: "Ele merece que lhe faças esta graça,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 5, 'porque é amigo da nossa nação, e até nos edificou a sinagoga."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 6, 'Jesus foi com eles. Quando estava já perto da casa, o centurião mandou-lhe amigos a dizer: Senhor, não te incomodes, porque eu não sou digno que entres sob o meu tecto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 7, 'Por essa razão nem eu me achei digno de ir ter contigo; mas diz uma só palavra, e o meu servo será curado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 8, 'Porque também eu, simples subalterno, tendo soldados às minhas ordens, e digo a um: Vai! e ele vai; e a outro: Vem! e ele vem; e ao meu servo: Faz isto! e ele o faz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 9, 'Jesus, ao ouvir isto, ficou admirado, e, voltando-se para a multidão que o seguia, disse: "Em verdade vos digo que não encontrei tanta fé em Israel."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 10, 'Voltando para casa os que tinham sido enviados, encontraram curado o servo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 11, 'No dia seguinte, foi ele para uma cidade, chamada Naim. Iam com ele os seus discípulos e muito povo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 12, 'Quando chegou perto da porta da cidade, eis que era levado um defunto a sepultar, filho único de uma viúva; e ia com muita gente da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 13, 'Tendo-a visto, o Senhor, movido de compaixão para com ela, disse-lhe: "Não chores."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 14, 'Aproximou-se, tocou no esquife, e os que o levavam pararam. Então disse: "Jovem, eu te ordeno, levanta-te."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 15, 'E sentou-se o que tinha estado morto, e começou a falar. Depois, Jesus, entregou-o a sua mãe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 16, 'Todos ficaram possuídos de temor, e glorificavam a Deus, dizendo: "Um grande profeta apareceu entre nós, Deus visitou o seu povo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 17, 'Esta opinião a respeito dele espalhou-se por toda a Judeia, e por toda a região circunvizinha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 18, 'Referiram a João os seus discípulos todas estas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 19, 'João chamou dois dos seus discípulos, enviou-os a Jesus a dizer-lhe: "És tu o que há-de vir ou devemos esperar outro?" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 20, 'Tendo ido ter com ele, disseram-lhe: João Baptista enviou-nos a ti, para te perguntar: "És tu o que há-de vir, ou devemos esperar outro?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 21, 'Naquela mesma ocasião Jesus curou muitos de enfermidades, de males, de espíritos malignos, e deu vista a muitos cegos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 22, 'Depois respondeu-lhes: "Ide referir a João o que vistes e ouvistes: Os cegos vêem, os coxos andam, os leprosos são limpos, os surdos ouvem, os mortos ressuscitam, aos pobres é anunciado o Evangelho;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 23, 'e bem-aventurado aquele que se não escandalizar a meu respeito."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 24, 'Tendo partido os mensageiros de João, começou Jesus a dizer acerca de João às turbas: "Que fostes vós ver ao deserto? Uma cana agitada pelo vento? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 25, 'Mas que fostes ver? Um homem vestido de roupas delicadas? Mas os que vestem roupas preciosas, e vivem entre delícias, são os que vivem nos palácios dos reis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 26, 'Que fostes ver? Um profeta? Sim, vos digo eu, e mais ainda que profeta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 27, 'Este é aquele de quem está escrito: Eis que eu envio o meu mensageiro adiante de ti, o qual preparará o teu caminho diante de ti Ml. 3, 1.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 28, 'Porque eu vos digo: Entre os nascidos das mulheres, não há maior profeta que João Baptista; porém, o que é menor do reino de Deus é maior do que ele." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 29, 'Todo o povo que o ouviu, mesmo os publicanos, deram glória a Deus, recebendo o baptismo de João.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 30, 'Os fariseus, porém, e os doutores da lei frustraram o desígnio de Deus a respeito deles, não se fazendo baptizar por ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 31, 'A quem pois compararei os homens desta geração? A quem são semelhantes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 32, 'São semelhantes aos meninos que estão sentados na praça, e que falam uns para os outros, dizendo; Tocámos flauta, e vós não bailastes; entoámos endeichas, e vós não chorastes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 33, 'Porque veio João Baptista, que não come pão, nem bebe vinho, e dizeis: Está possesso do demônio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 34, 'Veio o Filho do homem, que come e bebe, e dizeis: Eis um glutão e um bebedor de vinho, amigo dos publicanos e dos pecadores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 35, 'Mas a sabedoria foi justificada por todos os seus filhos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 36, 'Um dos fariseus pediu-lhe que fosse comer com ele. Tendo entrado em casa do fariseu, pôs-se à mesa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 37, 'Uma mulher, que era pecadora na cidade, quando soube que ele estava à mesa em casa do fariseu, levou um vaso de alabastro cheio de bálsamo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 38, 'Colocando-se a seus pés, por detrás dele, começou a banhar-lhe os pés com lágrimas, e os enxugava com os cabelos da sua cabeça, os beijava, e os ungia com o bálsamo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 39, 'Vendo isto o fariseu que o tinha convidado, disse consigo: "Se este fosse profeta, com certeza saberia quem e qual é a mulher que o toca: uma pecadora."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 40, 'Então, respondendo Jesus, disse-lhe: "Simão, tenho uma coisa a dizer-te." Ele disse: "Mestre, fala."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 41, '"Um credor tinha dois devedores: um devia-lhe quinhentos dinheiros, o outro cinquenta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 42, 'Não tendo eles com que pagar, perdoou a ambos a dívida. Qual deles, pois, mais o amará?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 43, 'Simão respondeu: "Creio que aquele a quem perdoou mais." Jesus disse-lhe: "Julgaste bem."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 44, 'Em seguida, voltando-se para a mulher, disse a Simão: "Vês esta mulher? Entrei em tua casa, não me deste água para os pés; ela com as suas lágrimas banhou os meus pés, e enxugou-os com os seus cabelos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 45, 'Não me deste o ósculo; porém ela, desde que entrou, não cessou de beijar os meus pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 46, 'Não ungiste a minha cabeça com bálsamo, porém esta ungiu com bálsamo os meus pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 47, 'Pelo que te digo : São-lhe perdoados muitos pecados, porque muito amou. Mas, ao que pouco se perdoa pouco ama."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 48, 'Depois disse à mulher: "São-te perdoados os pecados."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 49, 'Os convidados começaram a dizer entre si: "Quem é este que até perdoa pecados?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 50, 'Mas Jesus disse à mulher: "A tua fé te salvou; vai em paz."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 1, 'Em seguida Jesus caminhava pelas cidades e aldeias, pregando e anunciando a boa nova do reino de Deus; andavam com ele os doze'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 2, 'e algumas mulheres que tinham sido livradas de espíritos malignos e de enfermidades; Maria, chamada Madalena, da qual tinham saído sete demônios,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 3, 'Joana, mulher de Cusa, procurador de Herodes, Susana, e outras muitas, que lhe assistiam de suas posses.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 4, 'Tendo-se juntado uma grande multidão de povo, e, tendo ido ter com ele de diversas cidades, disse Jesus esta parábola:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 5, '"Saiu o semeador a semear a sua semente; ao semeá-la, uma parte caiu ao longo do caminho; foi calcada, e as aves do céu comeram-na.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 6, 'Outra parte caiu sobre pedregulho; quando nasceu, secou, porque não tinha humidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 7, 'A outra parte caiu entre os espinhos; logo os espinhos, que nasceram com ela, a sufocaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 8, 'Outra parte caiu em boa terra; depois de nascer, deu fruto, cento por um." Dito isto, exclamou: "Quem tem ouvidos para ouvir, ouça!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'Os seus discípulos perguntaram-lhe o que significava esta parábola.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 10, 'Ele respondeu-lhes: "A vós é concedido conhecer o mistério do reino de Deus, mas aos outros ele é anunciado por parábolas; para que vendo não vejam, e ouvindo não entendam (Is. 6, 9-10). (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 11, 'Eis o sentido da parábola: A semente é a palavra de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 12, 'Os que estão ao longo do caminho, são aqueles que a ouvem, mas depois vem o demónio e tira a palavra do seu coração para que não se salvem crendo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 13, 'Aqueles (em que se semeia) sobre pedregulho, são os que recebem com gosto a palavra, quando a ouvem, mas não têm raízes; até certo ponto crêem, mas, no tempo da tentação, voltam atrás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 14, 'A que caiu entre espinhos, representa aqueles que ouviram (a palavra), porém, indo por diante, ficam sufocados pelos cuidados, pelas riquezas, e pelos deleites desta vida, e não dão fruto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 15, 'Enfim, a que caiu em boa terra, representa aqueles que, ouvindo a palavra com coração recto e bom, a retêm e dão fruto por sua perseverança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 16, 'Ninguém, pois, acendendo uma lucerna, a cobre com um vaso ou a põe debaixo da cama, mas põe-na sobre um candeeiro, para que vejam a luz os que entram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 17, 'Porque nada há oculto que não acabe por ser manifestado, nem escondido que não deva saber-se e tornar-se público.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 18, 'Vede, pois, como ouvis. Porque àquele que tem, lhe será dado; e ao que não tem, ainda aquilo mesmo que julga ter, lhe será tirado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 19, 'Foram ter com ele sua mãe e seus irmãos, e não podiam aproximar-se dele por causa da multidão, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 20, 'Foram dizer-lhe: "Tua mãe e teus irmãos estão lá fora, e querem ver-te."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 21, 'Ele, respondeu-lhes: "Minha mãe e meus irmãos são aqueles que ouvem a palavra de Deus, e a praticam."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 22, 'Um dia, subiu com os seus discípulos para uma barca, e disse-lhes; "Passemos à outra margem do lago." Eles fizeram-se ao mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 23, 'Enquanto iam navegando, Jesus adormeceu. Levantou-se uma tempestade de vento sobre o lago, e a barca enchia-se de água, e estavam em perigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 24, 'Aproximando-se dele, despertaram-no, dizendo: "Mestre, Mestre! nós perecemos." Ele, levantando-se, increpou o vento e as ondas, que acalmaram, e veio a bonança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 25, 'Então disse-lhes: "Onde está a vossa fé?" Eles, cheios de temor, admiraram-se, dizendo uns para os outros: "Quem é este que manda aos ventos e ao mar, e eles lhe obedecem?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 26, 'Arribaram ao país dos Gerasenos, que está fronteiro à Galileia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 27, 'Logo que saltou em terra, foi ter com ele um homem daquele lugar, possesso de muitos demônios. Não se vestia há muito tempo, nem habitava em casa, mas nos sepulcros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 28, 'Logo que viu Jesus, prostrou-se diante dele, e começou a vociferar: "Que tens tu comigo, Jesus, Filho do Deus Altíssimo? Suplico-te que me não atormentes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 29, 'Porque Jesus mandava ao espírito imundo que saísse daquele homem, pois há muito tempo se tinha apoderado dele; estava preso com cadeias e grilhões, mas ele, quebradas as cadeias, era impelido pelo demônio para os desertos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 30, 'Jesus interrogou-o: "Que nome é o teu?" Ele respondeu : "Legião"; porque tinham entrado nele muitos demônios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 31, 'Estes suplicavam-lhe que os não mandasse ir para o abismo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 32, 'Ora andava por ali pastando no monte uma grande vara de porcos. Os demônios suplicavam-lhe que lhes permitisse entrar neles. Jesus lho permitiu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 33, 'Saíram, pois, do homem os demônios, entraram nos porcos; e logo a vara se precipitou com ímpeto por um despenhadeiro no lago, e se afogou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 34, 'Quando os guardas viram isto, fugiram, e foram contá-lo à cidade e pelas aldeias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 35, 'Saíram a ver o que tinha acontecido, foram ter com Jesus, encontraram sentado a seus pés, vestido e em seu juizo, o homem de quem tinham saído os demónios; e tiveram medo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 36, 'Os que tinham presenciado contaram-lhes como o possesso tinha sido livrado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 37, 'E todo o povo do país dos Gerasenos pediu (a Jesus) que se retirasse deles; porque estavam possuídos de grande temor. Ele, subindo para a barca, fez-se de volta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 38, 'O homem, de quem tinham saído os demônios, pedia-lhe que o deixasse estar com ele. Porém, Jesus o despediu dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 39, '"Volta para tua casa, e conta quanto Deus te fez." Ele foi e publicou por toda a cidade quanto Jesus lhe tinha feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 40, 'Tendo voltado Jesus, foi recebido pela multidão ; pois todos o estavam esperando,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 41, 'eis que veio um homem, chamado Jairo, que era o chefe da sinagoga; lançou-se aos pés de Jesus, implorando-lhe que fosse a sua casa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 42, 'porque tinha uma filha única com cerca de doze anos, que estava a morrer. Sucedeu que, enquanto Jesus ia caminhando, era apertado pelo povo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 43, 'Uma mulher, que padecia fluxo de sangue há doze anos, e tinha despendido com médicos todos os seus bens, sem poder ser curada por nenhum deles,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 44, 'aproximou-se por detrás e tocou a orla do seu vestido; imediatamente, parou o fluxo do seu sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 45, 'Jesus perguntou: "Quem me tocou?" Negando todos, disse Pedro (e os que com ele estavam) : "Mestre, as multidões apertam-te e oprimem-te."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 46, 'Mas Jesus disse: "Alguém me tocou, porque conheci que saiu de mim uma virtude."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 47, 'A mulher, vendo-se descoberta, aproximou-se tremendo, prostrou-se a seus pés, e declarou diante de todo o povo a causa por que o tinha tocado, e como ficara logo sã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 48, 'Jesus disse-lhe: "Filha, a tua fé te salvou; vai em paz."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 49, 'Ainda ele não tinha acabado de falar, quando veio um dizer ao chefe da sinagoga: "Tua filha morreu, não importunes mais o Mestre."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 50, 'Jesus, tendo ouvido estas palavras, disse ao pai da menina: "Não temas, crê sòmente e ela será salva."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 51, 'Tendo chegado a casa, não deixou entrar ninguém com ele, senão Pedro, Tiago e João, o pai e a mãe da menina.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 52, 'Entretanto todos choravam, e a lamentavam. Porém, ele disse-lhes: "Não choreis, (a menina) não está morta, mas dorme."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 53, 'Zombaram dele, sabendo que estava morta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 54, 'Então Jesus, tomando-a pela mão, disse em alta voz: "Menina, levanta-te."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 55, 'O seu espírito voltou, e levantou-se imediatamente. Ele mandou que lhe dessem de comer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 56, 'Seus pais ficaram cheios de assombro, e Jesus ordenou-lhes que não dissessem a ninguém o que tinha acontecido.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 1, 'Convocados os doze ( Apóstolos ) deu-lhes poder e autoridade sobre todos os demónios; e para curar as doenças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 2, 'Enviou-os a pregar o reino de Deus, e a curar os doentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 3, 'Disse-lhes : "Não leveis nada para o caminho, nem bastão, nem alforge, nem pão, nem dinheiro, nem leveis duas túnicas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 4, 'Em qualquer casa, em que entrardes, ficai lá, e ( não ) saiais dela até à vossa partida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 5, 'Quando quaisquer vos não receberem, ao sair dessa cidade, sacudi até o pó dos vossos pés, em testemunho contra eles."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 6, 'Tendo eles partido, andavam de aldeia em aldeia pregando o Evangelho, e fazendo curas por toda a parte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 7, 'Herodes tetrarca ouviu falar de tudo o que se passava, e não sabia que pensar, porque uns diziam:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 8, '"É João que ressuscitou dos mortos"; outros: "É Elias que apareceu"; outros: "É um dos antigos profetas, que ressuscitou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 9, 'Herodes disse: "Eu mandei degolar João. Quem é, pois, este de quem ouço tais coisas?" E buscava ocasião de o ver.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 10, 'Tendo voltado os Apóstolos, contaram-lhe tudo o que tinham feito. Ele, tomando-os consigo, retirou-se aparte a um lugar do território de Betsaida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 11, 'Sabendo isto, as multidões foram-no seguindo. E as recebeu, falou-lhes do reino de Deus e sarou os que necessitavam de cura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 12, 'Ora o dia começava a declinar. Aproximando-se dele os doze, disseram-lhe: "Despede as multidões, para que, indo pelas aldeias e herdades circunvizinhas, se alberguem e encontrem que comer, porque aqui estamos num lugar deserto."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 13, 'Ele respondeu-Ihes: "Dai-lhes vós de comer." Eles disseram: "Não temos mais do que cinco pães e dois peixes, a não ser que vamos comprar mantimento para toda esta multidão."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 14, 'Pois eram quase cinco mil homens. Então disse a seus discípulos: "Mandai-os sentar divididos em ranchos de cinquenta."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 15, 'Eles assim o executaram, e mandaram-nos sentar a todos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 16, 'Tendo tomado os cinco pães e os dois peixes, levantou os olhos ao céu, abençoou-os, partiu-os e distribuiu-os aos seus discípulos, para que os servissem à multidão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 17, 'Comeram todos, e ficaram saciados. E levantaram do que lhes sobejou doze cestos de fragmentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 18, 'Aconteceu que, estando só orando, se encontravam com ele os seus discípulos. Jesus interrogou-os: "Quem dizem as multidões que sou eu?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 19, 'Responderam e disseram: "Uns dizem que João Baptista, outros que Elias, outros que ressuscitou um dos antigos profetas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 20, 'Ele disse-lhes: "E vós quem dizeis que sou eu?" Pedro, respondendo, disse: "O Cristo de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 21, 'Mas ele, com seu tom severo, mandou que o não dissessem a ninguém,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 22, 'acrescentando: "É necessário que o Filho do homem padeça muitas coisas, que seja rejeitado pelos anciães, pelos príncipes doe sacerdotes e pelos escribas, que seja morto, e ressuscite ao terceiro dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 23, 'Depois, dirigindo-se a todos: "Se alguém quer vir após de mim, negue-se a si mesmo, tome a sua cruz todos os dias, e siga-me.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 24, 'Porque o que quiser salvar a sua vida (abandonando-me), a perderá; e quem perder a sua vida por causa de mim, salvá-la-á.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 25, 'Que aproveita o homem ganhar todo o mundo, se se perde a si mesmo, e se faz dano a si?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 26, 'Porque quem se envergonhar de mim e das minhas palavras, também o Filho do homem se envergonhará dele, quando vier na sua majestade, e na de seu Pai e dos santos anjos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 27, 'Digo-vos na verdade que estão aqui alguns presentes que não morrerão, sem que vejam o reino de Deus." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 28, 'Cerca de oito dias depois destas palavras, tomou consigo Pedro, Tiago e João, e subiu a um monte para orar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 29, 'Enquanto orava, tornou-se todo outro o seu rosto; o seu vestido tornou-se branco ( e ) resplandecente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 30, 'E eis que dois homens falavam com ele: Moisés e Elias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 31, 'os quais apareceram cheios de majestade, e falavam da morte que ele devia sofrer em Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 32, 'Entretanto Pedro e os que estavam com ele tinham-se deixado oprimir de sono. Mas, despertando, viram a majestade de Jesus, e os dois varões que estavam com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 33, 'Enquanto estes se separavam dele, Pedro disse a Jesus: "Mestre, é bom para nós estar aqui; façamos três tendas, uma para ti, uma para Moisés, e uma para Elias", não sabendo o que dizia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 34, 'Estando ele ainda a falar, formou-se uma nuvem, que os envolveu; e tiveram medo, quando os viram entrar na nuvem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 35, 'Então saiu uma voz da nuvem, dizendo: "Este é o meu filho dilecto, ouvi-o."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 36, 'Ao soar aquela voz, Jesus ficou só. Eles calaram-se, e a ninguém disseram naqueles dias nada do que tinham visto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 37, 'Sucedeu no dia seguinte que, descendo eles do monte, lhes saiu ao encontro uma grande multidão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 38, 'E eis que um homem do meio da multidão clamou; "Mestre, rogo-te que ponhas os olhos em meu filho, porque é o único que tenho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 39, 'Um espírito maligno se apodera dele e súbitamente dá gritos, e ( o lança por terra ), o agita com violência, fazendo-o espumar, e apenas o larga depois de o ter dilacerado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 40, 'Pedi a teus discípulos que o expelissem, mas eles não puderam."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 41, 'Jesus respondeu: "O ’ geração incrédula e perversa! Até quando estarei convosco e vos sofrerei? Traz cá o teu filho."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 41, 'Ó geração incrédula... Ver nota Mt. 18, 19.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 42, 'Quando este se aproximava, o demônio lançou-o por terra, e agitou-o com violência. Mas Jesus ameaçou o espírito imundo, sarou o menino, e restituiu-o a seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 43, 'E todos pasmavam da grandeza de Deus. Enquanto todos admiravam as coisas que ele fazia, Jesus disse aos seus discípulos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 44, '"Ponde nos vossos corações estas palavras: O Filho do homem está para ser entregue nas mãos dos homens."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 45, 'Eles, porém, não entendiam esta linguagem ; era-lhes tão obscura que não compreendiam; e tinham medo de o interrogar acerca dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 46, 'Começaram a discutir entre si sobre qual deles era o maior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 47, 'Jesus, vendo os pensamentos do seu coração, tomou pela mão um menino, pô-lo junto a si,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 48, 'e disse-lhes: "Todo o que receber este menino em meu nome, a mim recebe; e todo o que me receber, recebe aquele que me enviou. Porque aquele que entre vós todos é o menor, esse é o maior."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 49, 'João, tomando a palavra, disse: "Mestre, nós vimos um que expelia os demônios em teu nome, e lho proibimos, porque não anda connosco."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 50, 'Jesus respondeu-lhe: "Não lho proibais, porque quem não é contra vós, é por vós."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 51, 'Aconteceu que, aproximando-se o tempo da sua partida deste mundo, dirigiu-se resolutamente para Jerusalém,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 52, 'e enviou adiante de si mensageiros, os quais entraram numa aldeia de Samaritanos para lhe prepararem pousada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 53, 'Não o receberam, por dar mostras de que ia para Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 54, 'Vendo isto os seus discípulos Tiago e João, disseram : "Senhor, queres tu que digamos que desça fogo do céu, que os consuma?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 55, 'Ele, porém, voltando-se para eles, repreendeu-os: "Vós não sabeis de que espírito sois. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 56, 'O Filho do homem não veio para perder as vidas dos homens, mas para as salvar." E foram para outra povoação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 57, 'Indo eles pelo caminho, veio um homem que lhe disse: "Seguir-te-ei para onde quer que fores."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 58, 'Jesus respondeu-lhe: "As raposas têm suas covas, as aves do céu têm seus ninhos, porém o Filho do homem não tem onde reclinar a cabeça." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 59, 'A um outro disse: "Segue-me." Mas ele disse: "Senhor, permite-me que eu vá primeiro sepultar meu pai."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 60, 'Mas Jesus replicou: "Deixa que os mortos sepultem os seus mortos; tu vai anunciar o reino de Deus." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 61, 'Um outro disse-lhe: "Eu, Senhor, seguir-te-ei, mas permite que vá primeiro dizer adeus aos de minha casa."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 62, 'Jesus respondeu-lhe; "Ninguém que, depois de ter metido a sua mão ao arado, olha para trás, é apto para o reino de Deus. (ver nota)');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 1, 'Depois disto, o Senhor escolheu outros setenta e dois mandou-os dois a dois adiante de si por todas as cidades e lugares onde ele estava para ir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 2, 'Disse-lhes: "Grande é na verdade a messe, mas os operários poucos. Rogai, pois, ao dono da messe que mande operários para a sua messe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 3, 'Ide; eis que eu vos envio como cordeiros entre lobos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 4, 'Não leveis bolsa, nem alforge, nem calçado, e pelo caminho não saudeis ninguém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 5, 'Na casa em que entrardes, dizei primeiro: A paz seja nesta casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 6, 'Se ali houver algum filho de paz, repousará sobre ele a vossa paz; de contrário, tornará para vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 7, 'Permanecei na mesma casa, comendo e bebendo do que tiverem; porque o operário é digno da sua recompensa. Não andeis de casa em casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 8, 'Em qualquer cidade em que entrardes, e vos receberem, comei o que vos puserem diante;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 9, 'curai os enfermos que nela houver, e dizei-lhes: Está próximo de vós o reino de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 10, 'Mas, em qualquer cidade em que entrardes, e vos não receberem, saindo para as praças dizei; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 11, 'Até o pó da vossa cidade, que se nos pegou aos pés, sacudimos contra vós; não obstante isto, sabei que o reino de Deus está próximo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 12, 'Digo-vos que, naquele dia, haverá menos rigor para Sodoma que para essa cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 13, 'Ai de ti, Corozain! Ai de ti, Betsaida! Porque, se em Tiro e em Sidónia se tivessem operado as maravilhas que se têm operado em vós, há muito tempo que teriam feito penitência, cobertas de cilício, e jazendo sobre a cinza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 14, 'Por isso haverá no dia de juízo menos rigor para Tiro e Sidónia que para vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 15, 'E tu, Cafarnaum, que te elevas até ao céu, serás abatida até ao inferno (Is. 14, 13-15).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 16, 'O que vos ouve, a mim ouve, o que vos rejeita, a mim rejeita, e quem me rejeita, rejeita aquele que me enviou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 17, 'Os setenta e dois voltaram alegres, dizendo: "Senhor, até os demônios se nos submetem em virtude do teu nome."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 18, 'Ele disse-lhes: "Eu vi Satanás cair do céu como um raio. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 19, 'Eis que vos dei poder de caminhar impunemente sobre serpentes e escorpiões, e de vencer toda a força do inimigo, e nada vos fará dano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 20, 'Contudo não vos alegreis porque os espíritos maus vos estão sujeitos, mas alegrai-vos porque os vossos nomes estão escritos nos céus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 21, 'Naquela mesma hora Jesus exultou no Espírito Santo, e disse: "Graças te dou, ó Pai, Senhor do céu e da terra, porque escondeste estas coisas aos sábios e aos prudentes, e as revelaste aos pequeninos. Assim é, ó Pai, porque assim foi do teu agrado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 22, 'Todas as coisas me foram entregues por meu Pai; e ninguém sabe quem é o Filho, senão o Pai, nem quem é o Pai, senão o Filho, e aquele a quem o Filho quiser revelar."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 23, 'Depois, tendo-se voltado para seus discípulos, disse: "Ditosos os olhos que vêem o que vós vedes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 24, 'Porque eu vos afirmo que muitos profetas e reis desejaram ver o que vós vedes, e não viram, ouvir o que vós ouvis, e não o ouviram."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 25, 'Eis que se levantou um doutor da lei, e lhe disse para o tentar: "Mestre, que devo eu fazer para alcançar a vida eterna?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 26, 'Jesus respondeu-lhe: "O que é que está escrito na lei? Como lês tu?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 27, 'Ele respondeu: "Amarás o Senhor teu Deus com todo o teu coração, com toda a tua alma, com todas as tuas forças e com todo o teu entendimento, e o teu próximo como a ti mesmo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 28, 'Jesus disse-lhe: "Respondeste bem ; faz isso, e viverás (Lv. 18, 5)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 29, 'Mas ele, querendo justificar-se, disse a Jesus: "E quem é o meu próximo?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 30, 'Jesus, retomando a palavra, disse; "Um homem descia de Jerusalém para Jericó, e caiu nas mãos dos ladrões, que o despojaram, e, tendo-lhe feito feridas, retiraram-se, deixando-o meio morto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 31, 'Ora aconteceu que descia pelo mesmo caminho um sacerdote, o qual, quando o viu, passou de largo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 32, 'Igualmente um levita, chegando perto daquele lugar, e vendo-o, passou adiante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 33, 'Um samaritano, porém, que ia de viagem, chegou perto dele, e, quando o viu, moveu-se de compaixão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 34, 'Aproximou-se, ligou-lhe as feridas, lançando nelas azeite e vinho; e, pondo-o sobre o seu jumento, levou-o a uma estalagem, e teve cuidado dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 35, 'No dia seguinte tirou dois dinheiros, deu-os ao estalajadeiro, e disse-lhe: Tem cuidado dele; quanto gastares a mais, eu to satisferei quando voltar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 36, 'Qual destes três te parece que foi o próximo daquele que caiu nas mãos dos ladrões?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 37, 'Ele respondeu: "O que usou com ele de misericórdia." Então Jesus disse-lhe: "Vai, e faz tu o mesmo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 38, 'Indo em viagem, entrou em uma aldeia, e uma mulher, chamada Marta, recebeu-o em sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 39, 'Esta tinha uma irmã, chamada Maria que, sentada aos pés do Senhor, ouvia a sua palavra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 40, 'Marta, porém, afadigava-se muito na continua lida da casa. Aproximando-se, disse: "Senhor, não se te dá que minha irmã me tenha deixado só com o serviço da casa? Diz-lhe, pois, que me ajude."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 41, 'O Senhor, respondeu-lhe: "Marta, Marta, tu afadigas-te e andas inquieta com muitas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 42, 'Entretanto uma só coisa é necessária. Maria escolheu a melhor parte, que lhe não será tirada."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 1, 'Estando ele a fazer oração em certo lugar, quando acabou, um dos seus discípulos disse-lhe: "Senhor, ensina-nos a orar, assim como também João ensinou aos seus discípulos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 2, 'Ele respondeu-lhes: "Quando orardes, dizei: Pai, santificado seja o teu nome. Venha o teu reino.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 3, 'O pão nosso de cada dia nos dá hoje;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 4, 'perdoa-nos os nossos pecados, pois que também nós perdoámos aos que nos ofenderam; e não nos deixes cair em tentação."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 5, 'Disse-lhes mais: "Se algum de vós tiver um amigo, e for ter com ele à meia-noite para lhe dizer: "Amigo, empresta-me três pães,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 6, 'porque um meu amigo acaba de chegar a minha casa de uma viagem, e não tenho nada que lhe dar;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 7, 'e ele, respondendo lá de dentro, disser; Não me sejas importuno, a porta está agora fechada, os meus filhos e eu estamos deitados; não me posso levantar para tos dar...'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 8, 'digo-vos que, ainda que ele se não levantasse a dar-lhos, por ser seu amigo, certamente pela sua importunação se levantará, e lhe dará tudo aquilo de que precisar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 9, 'Eu digo-vos: Pedi, e dár-se-vos-á; buscai, e encontrareis; batei, e abrir-se-vos-á.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 10, 'Porque todo aquele que pede, recebe; e o que busca, encontra; e ao que bate, se lhe abrirá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 11, 'Se um filho pedir pão, qual é entre vós o pai que lhe dará uma pedra? Ou, se lhe pedir um peixe, dar-lhe-á ele, em vez do peixe, uma serpente?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 12, 'Ou se lhe pedir um ovo, porventura dar-lhe-á um escorpião?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 13, 'Se pois vós, sendo maus, sabeis dar boas dádivas a vossos filhos, quanto mais o vosso Pai celestial dará o Espírito Santo aos que lho pedirem."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 14, 'Jesus estava expelindo um demônio, que era mudo. Depois de ter expelido o demônio, o mudo falou, e as multidões ficaram maravilhadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 15, 'Mas alguns disseram: "Ele expele os demônios por virtude de Belzebu, príncipe dos demônios."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 16, 'Outros, para o tentarem, pediam-lhe um prodígio vindo do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 17, 'Ele, porém, conhecendo os seus pensamentos, disse-Ihes: "Todo o reino dividido contra si mesmo será devastado, e cairá casa sobre casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 18, 'Se, pois, Satanás está dividido contra si mesmo, como estará em pé o seu reino? Porque vós dizeis que por virtude de Belzebu é que eu lanço fora os demônios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 19, 'Ora, se é por virtude de Belzebu que eu lanço fora os demônios, vossos filhos por virtude de quem os expelem? Por isso eles mesmos serão os vossos juízes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 20, 'Mas se eu, pelo dedo de Deus, lanço fora os demônios, certamente chegou a vós o reino de Deus. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 21, 'Quando um valente armado, guarda o seu palácio, estão em segurança os bens que possui;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 22, 'porém, se, sobrevindo outro mais valente do que ele, o vencer, tira-lhe as armas, em que confiava, e reparte os seus despojos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 23, 'Quem não é comigo, é contra mim; e quem não colhe comigo desperdiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 24, 'Quando o espírito imundo saiu de um homem, anda por lugares secos, buscando repouso. Não o encontrando, diz: Voltarei para minha casa, donde sai. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 25, 'Quando vem, a encontra varrida e adornada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 26, 'Então vai, toma consigo outros sete espíritos piores do que ele, e, entrando, habitam ali. E o último estado daquele homem torna-se pior do que o primeiro."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 27, 'Aconteceu que, enquanto ele dizia estas palavras, uma mulher, levantando a voz do meio da multidão, disse-lhe: "Bem-aventurado o ventre que te trouxe, e os peitos a que foste amamentado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 28, 'Porém ele disse: "Antes bem-aventurados aqueles que ouvem a palavra de Deus, e a põem em prática." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 29, 'Concorrendo as multidões, começou a dizer: "Esta geração é uma geração perversa; pede um sinal, mas não lhe será dado outro sinal, senão o sinal do profeta Jonas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 30, 'Porque, assim como Jonas foi um sinal para os ninivitas, assim o Filho do homem será um sinal para esta geração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 31, 'A rainha do meio-dia levantar-se-á no dia de juízo contra os homens desta geração, e condená-los-á, porque veio da extremidade da terra ouvir a sabedoria de Salomão; entretanto, eis aqui está quem é mais do que Salomão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 32, 'Os ninivitas levantar-se-ão no (dia de) juízo contra esta geração, e condená-la-ão, porque fizeram penitência com a pregação de Jonas; entretanto eis aqui está quem é mais do que Jonas!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 33, 'Ninguém acende uma lucerna, e a põe em lugar escondido, nem debaixo do alqueire, mas sobre o candelabro, para que os que entram vejam a luz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 34, 'O teu olho é a lucerna do teu corpo. Se o teu olho for puro, todo o teu corpo terá luz; se, porém, for mau, também o teu corpo estará nas trevas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 35, 'Vê, pois, que a luz que está em ti não seja trevas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 36, 'Se, pois, o teu corpo for todo lúcido, sem ter parte alguma escura, todo ele será luminoso, e iluminar-te-á como uma lâmpada resplandecente."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 37, 'Enquanto Jesus falava, um fariseu convidou-o a ir jantar com ele. Tendo entrado, pôs-se à mesa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 38, 'Ora o fariseu estranhou que ele não se tivesse lavado antes de comer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 39, 'Mas o Senhor disse-lhe: "Agora vós os fariseus limpais o que está por fora do vaso e do prato; mas o vosso interior está cheio de rapina e de iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 40, 'Néscios, quem fez o que está de fora, não fez também o que está por dentro?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 41, 'Dai contudo esmola segundo os vossos meios, e tudo será puro para vós. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 42, 'Mas ai de vós, fariseus, que pagais o dízimo da hortelã, da arruda, de toda a casta de ervas, e desprezais a justiça e o amor de Deus! Era necessário praticar estas coisas, mas não omitir aquelas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 43, 'Ai de vós, fariseus, que gostais de ter as primeiras cadeiras nas sinagogas, e as saudações nas praças!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 44, 'Ai de vós, porque sois como os sepulcros que não se vêem, e sobre os quais se anda sem saber!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 45, 'Então um dos doutores da lei, tomando a palavra, disse-lhe: "Mestre, falando assim, também nos ofendes a nós."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 46, 'Jesus respondeu-lhe: "Ai de vós também, doutores da lei, porque carregais os homens de pesos que não podem suportar, e vós nem com um dedo vosso lhe tocais a carga!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 47, 'Ai de vós, que edificais sepulcros aos profetas, e foram vossos pais que lhes deram a morte!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 48, 'Por certo dais a conhecer que aprovais as obras de vossos pais; porque eles os mataram, e vós edificais os seus sepulcros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 49, 'Por isso disse a sabedoria de Deus: Mandar-lhes-ei profetas e apóstolos, e eles darão a morte a uns, e perseguirão outros,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 50, 'para que a esta geração se peça conta do sangue de todos os profetas, derramado desde o principio do mundo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 51, 'desde o sangue de Abel até ao sangue de Zacarias, que foi morto entre o altar e o templo. Sim, eu vos digo que será pedida conta disto a esta geração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 52, 'Ai de vós, doutores da lei, que usurpastes a chave da ciência, e nem entrastes vós, nem deixastes entrar os que queriam entrar!" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 53, 'Dizendo-lhes ele estas coisas, começaram os fariseus e doutores da lei a insistir fortemente, e a importuná-lo com muitas perguntas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 54, 'armando-lhe laços, e buscando ocasião de lhe apanharem da boca alguma palavra para o acusarem.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 1, 'Tendo-se juntado à roda de Jesus milhares e milhares de pessoas, de sorte que se atropelavam uns aos outros, começou ele a dizer aos seus discípulos: "Guardai-vos do fermento dos fariseus, que é a hipocrisia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 2, 'Nada há oculto que não venha a descobrir-se, e nada há escondido que não venha a saber-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 3, 'Por isso as coisas que dissestes nas trevas, serão ouvidas às claras, e o que falastes ao ouvido no gabinete, será apregoado sobre os telhados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 4, 'A vós, pois, meus amigos, vos digo: não tenhais medo daqueles que matam o corpo, e depois nada mais podem fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 5, 'Eu vou mostrar-vos a quem haveis de temer; temei aquele que, depois de matar, tem poder de lançar no inferno; sim, eu vos digo, temei este.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 6, 'Não se vendem cinco passarinhos por dois asses, entretanto nem um só deles está em esquecimento diante de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 7, 'Até os cabelos da vossa cabeça estão todos contados. Não temais pois; vós valeis mais que muitos passarinhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 8, 'Digo-vos: Todo aquele que me confessar diante dos homens, também o Filho do homem o confessará diante dos anjos de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 9, 'O que me negar diante dos homens, será negado diante dos anjos de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 10, 'Todo o que falar contra o Filho do homem, ser-lhe-á dado perdão; mas àquele que blasfemar contra o Espírito Santo, não lhe será perdoado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 11, 'Quando vos levarem às sinagogas, e perante os magistrados e autoridades, não estejais com cuidado de que modo respondereis, ou que direis,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 12, 'porque o Espírito Santo vos ensinará, naquele mesmo momento, o que deveis dizer."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 13, 'Então disse-lhe alguém da multidão: "Mestre, diz a meu irmão que me dê a minha parte da herança."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 14, 'Jesus respondeu-lhe: "Meu amigo, quem me constituiu juiz ou árbitro entre vós?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 15, 'Depois disse-lhes: "Guardai-vos cuidadosamente de toda a avareza, porque a vida de cada um, ainda que esteja na abundância, não depende dos bens que possui."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 16, 'Sobre isto propôs-lhes esta parábola: "Os campos de um homem rico tinham dado abundantes frutos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 17, 'Ele andava discorrendo consigo; Que farei, pois, não tenho onde recolher os meus frutos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 18, 'Depois disse: Farei isto: Demolirei os meus celeiros, fá-los-ei maiores, neles recolherei todas as minhas novidades e os meus bens,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 19, 'e direi à minha alma: Ó alma, tu tens muitos bens em depósito para largos anos; descansa, come, bebe, regala-te.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 20, 'Mas Deus disse-lhe: Néscio, esta noite te virão demandar a tua alma; e as coisas que juntaste, para quem serão?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 21, 'Assim é o que entesoura para si, e não é rico para Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 22, 'Depois disse a seus discípulos: "Portanto vos digo : Não andeis demasiadamente inquietos nem com o que vos é preciso para a vossa vida, nem com o que vos é preciso para vestir o vosso corpo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 23, 'A vida vale mais que o alimento, e o corpo mais que o vestido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 24, 'Considerai os corvos, que não semeiam, nem ceifam, nem têm despensa, nem celeiro, e Deus, contudo, sustenta-os. Quanto mais valeis vós do que eles?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 25, 'Qual de vós, por muito que pense, pode acrescentar um côvado à duração da sua vida?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 26, 'Se vós, pois, não podeis fazer o que é mínimo, porque estais em cuidado sobre as outras coisas?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 27, 'Considerai como crescem os lírios; não trabalham, nem fiam; contudo, digo-vos que nem Salomão, com toda a sua glória, se vestia como um deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 28, 'Se, pois, a erva, que hoje está no campo, e amanhã se lança no forno. Deus a veste assim, quanto mais a vós, homens de pouca fé?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 29, 'Vós, pois, não procureis com cuidados excessivos o que haveis de comer ou beber; não andeis com o espírito preocupado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 30, 'Porque são as nações deste mundo que buscam com excessivo cuidado todas estas coisas. Mas o vosso Pai sabe que tendes necessidade delas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 31, 'Buscai, pois, em primeiro lugar, o reino de Deus e a sua justiça, e todas essas coisas vos serão dadas por acréscimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 32, 'Não temas, ó pequenino rebanho, porque foi do agrado do vosso Pai dar-vos o reino.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 33, 'Vendei o que possuis, e dai esmola; provei-vos de bolsas que não envelhecem, de um tesouro inexaurível no céu, onde não chega o ladrão, nem a traça rói.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 34, 'Porque onde está o vosso tesouro, aí estará também o vosso coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 35, 'Estejam cingidos os vossos rins, e acesas as vossas lâmpadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 36, 'Fazei como os homens que esperam o seu senhor quando volta das bodas, para que, quando vier e bater à porta, logo lha abram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 37, 'Bem-aventurados aqueles servos, a quem o Senhor achar vigiando, quando vier. Na verdade vos digo que se cingirá, os fará pôr à mesa, e, passando por entre eles, os servirá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 38, 'Se vier na segunda vigília, ou na terceira, e assim os encontrar, bem-aventurados são aqueles servos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 39, 'Sabei que, se o pai de família soubesse a hora, em que viria o ladrão, vigiaria sem dúvida, e não deixaria minar a sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 40, 'Vós, pois, estai preparados, porque, na hora que não cuidais, virá o Filho do homem."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 41, 'Pedro disse-lhe: "Senhor, dizes esta parábola só para nós ou para todos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 42, 'O Senhor respondeu: "Quem é o despenseiro fiel e prudente que o Senhor estabelecerá sobre as pessoas da sua casa, para dar a cada um a seu tempo a ração de trigo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 43, 'Bem-aventurado aquele servo a quem, quando o Senhor vier, achar procedendo assim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 44, 'Na verdade vos digo que o constituirá administrador de tudo quanto possui.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 45, 'Porém, se aquele servo disser no seu coração : "O meu senhor tarda em vir ; e começar a espancar os criados e as criadas, a comer, a beber e a embriagar-se,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 46, 'chegará o senhor desse servo no dia, em que ele o não espera, e na hora, em que ele não sabe; removê-lo-á, e pô-lo-á aparte com os infiéis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 47, 'Aquele servo, que conheceu a vontade do seu senhor, e nada preparou, e não procedeu conforme a sua vontade, levará muitos açoutes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 48, 'Quanto àquele que, não a conhecendo, fez coisas dignas de castigo, levará poucos açoutes. Porque a todo aquele a quem muito foi dado, muito lhe será exigido; e ao que muito confiaram, mais conta lhe tomarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 49, 'Eu vim trazer fogo à terra; e que quero eu, senão que ele se acenda? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 50, 'Eu tenho de receber um baptismo; e quão grande é a minha ansiedade, até que ele se conclua! (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 51, 'Julgais que vim trazer paz à terra? Não, vos digo eu, mas separação ; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 52, 'porque, de hoje em diante, haverá numa casa cinco pessoas, divididas três contra duas, e duas contra três,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 53, 'Estarão divididos: o pai contra o filho, e o filho contra o pai; a mãe contra a filha, e a filha contra a mãe; a sogra contra a nora e a nora contra a sogra."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 54, 'Dizia também às multidões: "Quando vós vedes levantar-se uma nuvem no poente, logo dizeis: Aí vem chuva; e assim sucede.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 55, 'E quando sentis soprar o vento do sul, dizeis: Haverá calor; e assim sucede.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 56, 'Hipócritas, sabeis distinguir os aspectos da terra e do céu ; como, pois, não sabeis reconhecer o tempo presente?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 57, 'E porque não discernis também por vós mesmos o que é justo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 58, 'Quando, pois, fores com o teu adversário ao magistrado, faz o possível por te livrares dele no caminho, para que não suceda que te leve ao juiz, que o juiz te entregue ao meirinho, e o meirinho te meta na cadeia. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 59, 'Digo-te que não sairás de lá, enquanto não pagares até ao último ceitil."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 1, 'Neste mesmo tempo chegaram alguns a dar-lhe a notícia de certos galileus, cujo sangue Pilatos misturara com o dos sacrifícios deles. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 2, 'Jesus respondeu-lhes; "Vós julgais que aqueles galileus eram maiores pecadores que todos os outros galileus, por terem padecido tanto?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 3, 'Não, eu vo-lo digo; mas, se não fizerdes penitência, todos perecereis do mesmo modo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 4, 'Assim como também aqueles dezoito homens, sobre os quais caiu a torre de Siloé, e os matou, julgais que eles também foram mais culpados que todos os outros habitantes de Jerusalém?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 5, 'Não, eu vo-lo digo; mas, se não fizerdes penitência, todos perecereis do mesmo modo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 6, 'Dizia também esta parábola: "Um homem tinha uma figueira plantada na sua vinha. Foi buscar fruto, e não o encontrou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 7, 'Então disse ao cultivador da vinha: Eis que há três anos venho buscar fruto a esta figueira, e não o encontro; corta-a; para que está ela ocupando terreno inutilmente?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 8, 'Ele, porém, respondeu-lhe: Senhor, deixa-a ainda este ano, enquanto eu a cavo em roda, e lhe lanço esterco;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 9, 'se com isto der fruto, bem está, senão, cortá-la-ás depois."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 10, 'Jesus estava ensinando numa sinagoga em dia de sábado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 11, 'Estava lá uma mulher possessa de um espírito que a tinha doente havia dezoito anos; andava encurvada, e não podia absolutamente levantar a cabeça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 12, 'Jesus, vendo-a, chamou-a, e disse-lhe; "Mulher, estás livre da tua enfermidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 13, 'impôs-Ihe as mãos. Imediatamente ficou direita, e glorificava a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 14, 'Mas, tomando a palavra o príncipe da sinagoga, indignado de que Jesus tivesse curado em dia de sábado, disse ao povo: "Há seis dias para trabalhar; vinde, pois, nestes, e sede curados, mas não em dia de sábado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 15, 'O Senhor disse-lhe: "Hipócritas, qualquer de vós não solta aos sábados o seu boi ou seu jumento da manjedoura, para os levar a beber?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 16, 'E esta filha de Abraão, que Satanás tinha presa, há dezoito anos não devia ser livre desta prisão ao sábado?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 17, 'Dizendo estas coisas, envergonhavam-se todos os seus adversários, e alegrava-se todo o povo de todas as acções que gloriosamente eram praticadas por ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 18, 'Dizia também: "A que é semelhante o reino de Deus, a que o compararei eu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 19, 'É semelhante a um grão de mostarda, que um homem tomou e semeou na sua horta; cresceu, tornou-se uma grande planta, e as aves do céu repousaram nos seus ramos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 20, 'Disse outra vez : ''A que direi que o reino de Deus é semelhante?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 21, 'É semelhante ao fermento que uma mulher tomou e misturou em três medidas de farinha, até que ficasse tudo levedado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 22, 'Ia pelas cidades e aldeias ensinando, e caminhando para Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 23, 'Alguém lhe perguntou: "Senhor, são poucos os que se salvam?" Ele respondeu-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 24, '"Esforçai-vos por entrar pela porta estreita, porque vos digo que muitos procurarão entrar, e não conseguirão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 25, 'Quando o pai de família tiver entrado e fechado a porta, vós, estando fora, começareis a bater à porta, dizendo: Senhor, abre-nos, ele vos responderá: Não sei donde vós sois.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 26, 'Então começareis a dizer: Comemos e bebemos em tua presença, tu ensinaste nas nossas praças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 27, 'Ele vos dirá: Não sei donde sois; apartai-vos de mim vós todos os que praticais a iniquidade (Ps. 6, 9).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 28, 'Ali haverá choro e ranger de dentes, quando virdes Abraão, Isaac, Jacob, e todos os profetas no reino de Deus, e vós serdes expulsos para fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 29, 'Virão muitos do oriente, do ocidente, do norte, do sul, e se sentarão à mesa no reino de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 30, 'Então haverá últimos que serão os primeiros, e primeiros que serão os últimos." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 31, 'No mesmo dia alguns dos fariseus foram dizer-Ihe: "Sai, e vai-te daqui: porque Herodes quer-te matar."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 32, 'Ele respondeu-lhes: "Ide dizer a essa raposa: Eis que eu lanço fora os demônios, e faço curas: hoje e amanhã, e ao terceiro dia estou no termo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 33, 'Importa, contudo, que eu caminhe ainda hoje, amanhã e no dia seguinte; porque não convém que um profeta morra fora de Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 34, 'Jerusalém, Jerusalém, que matas os profetas e apedrejas os que te são enviados, quantas vezes quis juntar os teus filhos como a galinha recolhe os seus pintainhos debaixo das asas, e tu não quiseste!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 35, 'Eis vos será deixada deserta a vossa casa. Digo-vos que não me vereis, até que venha o dia em que digais: Bendito o que vem em nome do Senhor (Ps. 117, 26)." (ver nota)');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 1, 'Entrando Jesus, um sábado, em casa de um dos principais fariseus, a tomar a sua refeição, eles o estavam observando.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 2, 'Encontrava-se diante dele um homem hidrópico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 3, 'Jesus, dirigindo a palavra aos doutores da lei e aos fariseus, disse-lhes : "É licito ou não fazer curas ao sábado?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 4, 'Eles ficaram calados. Então Jesus, pegando no homem pela mão, curou-o e mandou-o embora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 5, 'Dirigindo-se depois a eles, disse: "Quem de entre vós que, se o seu filho ou o seu boi cair num poço, o não tirará logo ainda que seja em dia de sábado?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 6, 'Eles não sabiam que replicar a isto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 7, 'Disse também uma parábola, observando como os convidados escolhiam os primeiros lugares à mesa:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 8, '"Quando fores convidado para bodas, não te ponhas no primeiro lugar, porque pode ser que outra pessoa de mais consideração do que tu tenha sido convidada pelo dono da casa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 9, 'e que, vindo este que te convidou a ti e a ele, te diga: Cede o lugar a este; e tu envergonhado vás ocupar o último lugar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 10, 'Mas, quando fores convidado, vai tomar o último lugar, para que, quando vier o que te convidou, te diga : Amigo, vem mais para cima. Então terás com isto glória na presença dos que estiverem juntamente à mesa;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 11, 'porque todo o que se exalta, será humilhado, e o que se humilha, será exaltado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 12, 'Dizia mais ao que o tinha convidado : "Quando deres algum jantar ou ceia, não convides os teus amigos, nem os teus irmãos, nem os parentes, nem os vizinhos ricos; para que não aconteça que também eles te convidem, e te paguem com isso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 13, 'Mas, quando deres algum banquete, convida pobres, aleijados, coxos, cegos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 14, 'e serás bem-aventurado, porque esses não têm com que retribuir; mas ser-te-á isso retribuído na ressurreição dos justos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 15, 'Tendo ouvido estas coisas um dos convivas disse-lhe: "Bem-aventurado o que participar do banquete no reino de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 16, 'Jesus respondeu-lhe: "Um homem fez uma grande ceia, para a qual convidou muitos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 17, 'À hora da ceia, mandou um seu servo dizer aos convidados : Vinde, porque tudo está preparado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 18, 'Mas todos à uma começaram a escusar-se. O primeiro disse-lhe: Comprei um campo, e é-me necessário ir vê-lo; rogo-te que me dês por escusado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 19, 'Outro disse: Comprei cinco juntas de bois, e vou experimentá-los; rogo-te que me dês por escusado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 20, 'Disse também outro : Casei-me, por isso não posso ir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 21, 'Voltando o servo, referiu estas coisas ao seu senhor. Então, irado o pai de família, disse ao seu servo: Vai já pelas praças e pelas ruas da cidade; traz cá os pobres, os aleijados, os cegos e os coxos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 22, 'Disse o servo: Senhor, está feito como mandaste, e ainda há lugar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 23, 'Disse o senhor ao servo: Vai pelos caminhos e ao longo dos cercados ; e força-os a vir, para que se encha a minha casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 24, 'Porque eu vos digo que nenhum daqueles que foram convidados provará a minha ceia."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 25, 'Ia com ele grande multidão de povo. Jesus, voltando-se, disse-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 26, '"Se algum vem a mim, e não aborrece seu pai, sua mãe, sua mulher, seus filhos, seus irmãos, suas irmãs, e até a sua vida, não pode ser meu discípulo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 27, 'O que não leva a sua cruz e não me segue, não pode ser meu discípulo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 28, 'Porque qual de vós, querendo edificar uma torre, não se assenta primeiro para calcular a despesa e ver se tem com que acabar?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 29, 'Para que, depois de ter assentado o fundamento e não a poder terminar, todos os que virem, não comecem a fazer zombaria dele, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 30, 'Este homem principiou a edificar, e não pôde terminar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 31, 'Ou qual é o rei que, estando para entrar em guerra contra outro rei, não se assenta primeiro a considerar se com dez mil homens pode ir encontrar-se com o que traz contra ele vinte mil?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 32, 'Doutra maneira, quando o outro está ainda longe, enviando embaixadores, pede-Ihe paz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 33, 'Assim, pois, qualquer de vós que não renuncia tudo o que possui, não pode ser meu discípulo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 34, 'O sal é bom ; porém, se o sal perder a força, com que se há-de temperar?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 35, 'Não é bom nem para a terra, nem para estrume; mas será lançado fora. O que tem ouvidos para ouvir, ouça."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 1, 'Aproximavam-se dele os publicanos e os pecadores para o ouvir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 2, 'Os fariseus e os escribas murmuravam, dizendo: "Este recebe os pecadores, e come com eles."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 3, 'Então propôs-lhes esta parábola:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 4, '"Qual de vós, tendo cem ovelhas, se perde uma delas, não deixa as noventa e nove no deserto, para ir procurar a que se tinha perdido, até que a encontre?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 5, 'E, tendo-a encontrado, a põe sobre os ombros todo contente,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 6, 'e, indo para casa, chama os seus amigos e vizinhos, dizendo-Ihes: Congratulai-vos comigo, porque encontrei a minha ovelha, que se tinha perdido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 7, 'Digo-vos que, do mesmo modo, haverá maior júbilo no céu por um pecador que fizer penitência, que por noventa e nove justos que não têm necessidade de penitência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 8, 'Ou qual é a mulher que, tendo dez dracmas, e perdendo uma, não acende a candeia, não varre a casa, e não procura diligentemente até que a encontre?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 9, 'E que, depois de a achar, não convoca as amigas e vizinhas, dizendo: "Congratulai-vos comigo, porque encontrei a dracma que tinha perdido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 10, 'Assim vos digo eu que haverá júbilo entre os anjos de Deus por um só pecador que faça penitência."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 11, 'Disse mais: "Um homem tinha dois filhos, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 12, 'o mais novo disse a seu pai: Pai, dá-me a parte dos bens que me toca. O pai repartiu entre eles os bens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 13, 'Passados poucos dias, juntando tudo o que era seu, o filho mais novo partiu para uma terra distante, e lá dissipou os seus bens, vivendo dissolutamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 14, 'Depois de ter consumido tudo, houve naquele país uma grande fome, e ele começou a sentir necessidade. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 15, 'Foi pôr-se ao serviço de um habitante daquela terra, que o mandou para os seus campos guardar porcos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 16, 'Desejava encher o seu ventre das landes que os porcos comiam, mas ninguém lhas dava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 17, 'Tendo entrado em si, disse: Quantos jornaleiros há em casa de meu pai, que têm pão em abundância, e eu aqui morro de fome!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 18, 'Levantar-me-ei, irei ter com meu pai, e lhe direi: Pai, pequei contra o céu e contra ti;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 19, 'já não sou digno de ser chamado teu filho; trata-me como um dos teus jornaleiros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 20, 'Levantando-se, foi para seu pai. Quando ele estava ainda longe, seu pai viu-o, ficou movido de compaixão, e, correndo, lançou-lhe os braços ao pescoço, e beijou-o. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 21, 'O filho disse-lhe: Pai, pequei contra o céu e contra ti; já não sou digno de ser chamado teu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 22, 'Porém o pai disse aos seus servos: Trazei depressa o vestido mais precioso, vesti-lho, metei-lhe um anel no dedo e os sapatos nos pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 23, 'Trazei também um vitelo gordo, matai-o. Comamos e façamos festa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 24, 'porque este meu filho estava morto, e reviveu; tinha-se perdido, e foi encontrado. E começaram a fazer festa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 25, 'Ora o filho mais velho estava no campo. Quando voltou, ao aproximar-se de casa, ouviu a música e os coros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 26, 'Chamou um dos servos, e perguntou-lhe que era aquilo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 27, 'Este disse-lhe: Teu irmão voltou, e teu pai mandou matar um novilho gordo, porque o recuperou com saúde.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 28, 'Ele indignou-se, e não queria entrar. Mas o pai, saindo, começou a pedir-lhe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 29, 'Ele, porém, respondeu a seu pai: Há tantos anos que te sirvo, nunca transgredi nenhum mandado teu, e nunca me deste um cabrito para eu me banquetear com os meus amigos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 30, 'mas, logo que veio este teu filho, que devorou os seus bens com meretrizes, lhe mandaste matar um novilho gordo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 31, 'Seu pai disse-lhe: Filho, tu estás sempre comigo, tudo o que é meu é teu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 32, 'Era, porém, justo que houvesse banquete e festa, porque este teu irmão estava morto e reviveu; tinha-se perdido e foi encontrado".');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 1, 'Disse também a seus discípulos; "Um homem rico tinha um feitor, que foi acusado diante dele de ter dissipado os seus bens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 2, 'Chamou-o, e disse-lhe : Que é isto que ouço dizer de ti? Dá conta da tua administração; não mais poderás ser meu feitor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 3, 'Então o feitor disse consigo: Que farei, visto que o meu senhor me tira a administração? Cavar não posso, de mendigar tenho vergonha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 4, 'Já sei o que hei-de fazer, para que, quando for removido da administração, haja quem me receba em sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 5, 'Tendo chamado cada um dos devedores do seu senhor, disse ao primeiro: Quanto deves ao meu senhor?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 6, 'Ele respondeu: Cem cados de azeite. Então disse-lhe : Toma a tua caução, senta-te e escreve depressa cinquenta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 7, 'Depois disse a outro: Tu quanto deves? Ele respondeu: Cem medidas de trigo. Disse-lhe o feitor: Toma a tua caução e escreve oitenta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 8, 'E o senhor louvou o feitor iníquio, por ter procedido sagazmente. Porque os filhos deste século são mais hábeis no trato com os seus semelhantes que os filhos da luz. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 9, 'Portanto eu vos digo: Granjeai amigos com as riquezas da iniquidade, para que, quando vierdes a precisar, vos recebam nos tabernáculos eternos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 10, 'O que é fiel no pouco, também é fiel no muito; e o que é injusto no pouco, também é injusto no muito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 11, 'Se, pois, vós não fostes fiéis nas riquezas iníquas, quem fiará de vós as verdadeiras? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 12, 'E se vós não fostes fiéis no alheio, quem vos dará o que é vosso? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 13, 'Nenhum servo pode servir a dois senhores, porque ou odiará um, e amará o outro, ou se afeiçoará a um, e desprezará o outro. Não podeis servir Deus e o dinheiro." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 14, 'Ora os fariseus, que eram amigos do dinheiro, ouviam todas estas coisas, e zombavam dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 15, 'Jesus disse-lhes: "Vós sois aqueles que pretendeis passar por justos diante dos homens, mas Deus conhece os vossos corações; o que é excelente segundo os homens, é abominação diante de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 16, 'A lei e os profetas duraram até João; desde então é anunciado o reino de Deus, e todos se esforçam por entrar nele pela violência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 17, 'Ora é mais fácil passar o céu e a terra, do que perder-se um til da lei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 18, 'Todo o que repudia sua mulher, e toma outra, comete adultério ; e o que casa com a que foi repudiada por seu marido, comete adultério.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 19, 'Havia um homem rico, que se vestia de púrpura e de linho fino, e todos os dias se banqueteava esplêndidamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 20, 'Havia também um mendigo, chamado Lázaro, que, coberto de chagas, estava deitado à sua porta,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 21, 'desejando saciar-se com as migalhas que caiam da mesa do rico... e até os cães vinham lamber-Ihe as chagas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 22, 'Sucedeu morrer o mendigo, e foi levado pelos anjos ao seio de Abraão. Morreu também o rico, e foi sepultado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 23, 'Quando estava nos tormentos do inferno, levantando os olhos, viu ao longe Abraão, e Lázaro no seu seio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 24, 'Então exclamou; Pai Abraão, compadece-te de mim, e manda Lázaro que molhe em água a ponta do seu dedo, para refrescar a minha língua, pois sou atormentado nesta chama.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 25, 'Abraão disse-lhe: Filho, lembra-te que recebeste os teus bens em tua vida, e Lázaro, ao contrário, recebeu males; por isso ele é agora consolado, e tu és atormentado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 26, 'Além disso, há entre nós e vós um grande abismo; de maneira que os que querem passar daqui para vós, não podem, nem os daí podem passar para nós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 27, 'O rico disse: Rogo-te, pois, ó pai, que o mandes à minha casa paterna,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 28, 'pois tenho cinco irmãos, para que os advirta disto, e não suceda virem também eles parar a este lugar de tormentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 29, 'Abraão disse-lhe: Têm Moisés e os profetas; ouçam-nos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 30, 'Ele, porém, disse: Não basta isso pai Abraão, mas, se algum dos mortos for ter com eles, farão penitência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 31, 'Ele disse-Ihe: Se não ouvem Moisés e os profetas, tão-pouco acreditarão, ainda que ressuscitasse algum dos mortos."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 1, 'Depois Jesus disse a seus discípulos: "É impossível que não venham escândalos, porém, ai daquele por quem eles vêm !'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 2, 'Seria melhor para ele que lhe fosse posta ao pescoço a mó de um moinho, e que fosse precipitado no mar, do que ser causa de escândalo para um destes pequeninos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 3, 'Estai com cuidado sobre vós. Se teu irmão pecar, repreende-o; e, se ele se arrepender, perdoa-lhe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 4, 'E, se pecar sete vezes no dia contra ti e sete vezes no dia for ter contigo, dizendo: Estou arrependido, perdoa-lhe."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 5, 'Os apóstolos disseram ao Senhor: "Aumenta-nos a fé."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 6, 'O Senhor disse-lhes: "Se tiverdes fé como um grão de mostarda, direis a esta amoreira: Arranca-te e transplanta-te para o mar, e ela vos obedecerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 7, 'Qual é de vós, tendo um servo a lavrar ou a guardar gado, lhe dirá quando ele voltar do campo: Vem depressa, põe-te à mesa?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 8, 'Não lhe dirá antes: Prepara-me a ceia, cinge-te, e serve-me, enquanto eu como e bebo; depois comerás tu e beberás?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 9, 'Porventura, fica o senhor obrigado àquele servo, por ter feito o que lhe tinha mandado?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 10, 'Assim também vós, depois de terdes feito tudo o que vos foi mandado, dizei: Somos servos inúteis; fizemos o que devíamos fazer."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 11, 'Indo Jesus para Jerusalém, passou pela Samaria e pela Galileia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 12, 'Ao entrar numa aldeia, saíram-lhe ao encontro dez homens leprosos, que pararam ao longe,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 13, 'e levantaram a voz, dizendo: "Jesus, Mestre, tem compaixão de nós."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 14, 'Tendo-os ele visto, disse-lhes: "Ide, mostrai-vos aos sacerdotes." Aconteceu que, enquanto iam, ficaram limpos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 15, 'Um deles, quando viu que tinha ficado limpo, voltou atrás, glorificando a Deus em alta voz,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 16, 'e prostrou-se por terra a seus pés, dando-lhe graças. Era um samaritano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 17, 'Jesus disse: "Não são dez os que foram curados? Os outros nove onde estão?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 18, 'Não se encontrou quem voltasse, e desse glória a Deus, senão este estrangeiro?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 19, 'Depois disse-lhe: Levanta-te, vai; a tua fé te salvou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 20, 'Tendo-lhe os fariseus perguntado quando viria o reino de Deus, respondeu-lhes: " O reino de Deus não virá com aparato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 21, 'Não se dirá: Ei-lo aqui ou ei-lo acolá. Porque eis que o reino de Deus está no meio de vós." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 22, 'Depois disse aos seus discípulos: "Virá tempo em que vós desejareis ver um só dos dias do Filho do homem, e não o vereis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 23, 'E vos dirão: Ei-lo aqui, ou ei-lo acolá. Não vades, nem os sigais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 24, 'Porque, assim como o clarão brilhante de um relâmpago ilumina o céu de uma extremidade à outra, assim será o Filho do homem no seu dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 25, 'Mas primeiro é necessário que ele sofra muito, e seja rejeitado por esta geração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 26, 'Como sucedeu nos dias de Noé, assim sucederá também quando vier o Filho do homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 27, 'Comiam, bebiam, tomavam mulher e marido, até ao dia em que Noé entrou na arca; e veio o dilúvio, que exterminou a todos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 28, 'Como sucedeu também no tempo de Lot; comiam, bebiam, compravam, vendiam, plantavam e edificavam;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 29, 'mas, no dia em que Lot saiu de Sodoma, choveu fogo e enxofre do céu, que exterminou a todos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 30, 'Assim será no dia em que se manifestar o Filho do homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 31, 'Nesse dia quem estiver no terraço e tiver os seus móveis em casa, não desça a tomá-los; da mesma sorte, quem estiver no campo, não volte atrás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 32, 'Lembrai-vos da mulher de Lot.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 33, 'O que procurar salvar a sua vida, perdê-la-á; o que a perder, salvá-la-á. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 34, 'Eu vos digo: Nessa noite, de duas pessoas que estiverem num leito, uma será tomada, a outra deixada. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 35, 'Duas mulheres estarão moendo juntas, uma será tomada, a outra deixada; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 36, 'dois estarão no campo, um será tomado, o outro deixado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 37, 'Os discípulos disseram-lhe: "Onde será isso, Senhor?" (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 38, 'Ele respondeu-lhes: "Onde quer que estiver o corpo, juntar-se-ão aí também as águias."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 1, 'Disse-lhes também uma parábola, para mostrar que importa orar sempre e não cessar de o fazer:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 2, '"Havia em certa cidade um juiz, que não temia a Deus, nem respeitava os homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 3, 'Havia também na mesma cidade uma viúva, que ia ter com ele, dizendo: Faz-me justiça contra o meu adversário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 4, 'Ele, durante muito tempo, não quis atender. Mas depois disse consigo: Ainda que eu não temo a Deus, nem respeito os homens,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 5, 'todavia, visto que esta viúva me importuna, far-lhe-ei justiça, para que não venha continuamente importunar-me."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 6, 'Então o Senhor acrescentou : "Ouvi o que diz este juiz iníquo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 7, 'E Deus não fará justiça aos seus escolhidos, que estão clamando a ele, de dia e de noite, e tardará em os socorrer?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 8, 'Digo-vos que depressa lhes fará justiça. Mas, quando vier o Filho do homem, julgais vós que encontrará fé sobre a terra?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 9, 'Disse também esta parábola a uns que confiavam muito em si mesmos, como se fossem justos, e desprezavam os outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 10, '"Subiram dois homens ao templo a fazer oração: um era fariseu, outro publicano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 11, 'O fariseu, de pé, orava no seu interior desta forma: Graças te dou, ó Deus, porque não sou como os outros homens: ladrões, injustos, adúlteros, nem como este publicano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 12, 'Jejuo duas vezes na semana; pago o dízimo de tudo o que possuo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 13, 'O publicano, porém, conservando-se a distância, não ousava nem ainda levantar os olhos ao céu, mas batia no peito, dizendo: Meu Deus, tem piedade de mim pecador.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 14, 'Digo-vos que este voltou justificado para sua casa, o outro não; porque quem se exalta será humilhado, e quem se humilha será exaltado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 15, 'Traziam-lhe também meninos, para que os tocasse. Vendo isto os discípulos repreendiam-nos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 16, 'Porém Jesus, chamando-os a si, disse: "Deixai vir a mim os meninos, e não os embaraceis, porque o reino de Deus é dos que se parecem com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 17, 'Em verdade vos digo: O que não receber o reino de Deus como um menino, não entrará nele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 18, 'Então um dos principais fez-lhe esta pergunta: "Bom Mestre, que devo eu fazer para obter a vida eterna?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 19, 'Jesus respondeu-lhe: "Porque me chamas bom? Ninguém é bom senão só Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 20, 'Tu conheces os mandamentos: não matarás, não cometerás adultério, não furtarás, não dirás falso testemunho, honra teu pai e tua mãe (Ex. 20, 12-16 ; Dt. 5, 16-20)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 21, 'Ele disse: "Tenho observado tudo isso desde a minha juventude."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 22, 'Tendo Jesus ouvido isto, disse-Ihe: "Ainda te falta uma coisa: Vende tudo quanto tens, dá-o aos pobres, e terás um tesouro no céu; depois vem, segue-me." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 23, 'Mas ele, ouvindo isto, entristeceu-se, porque era muito rico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 24, 'Jesus, vendo esta tristeza, disse : "Quanto é difícil que aqueles que têm riquezas entrem no reino de Deus! (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 25, 'É mais fácil passar um camelo pelo fundo de uma agulha, do que entrar um rico no reino de Deus." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 26, 'Os que o ouviam disseram: "Quem pode, pois, salvar-se?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 27, 'Jesus respondeu-lhes: "O que é impossível aos homens, é possível a Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 28, 'Então disse Pedro : "Eis que deixámos tudo para te seguir."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 29, 'Ele disse-lhes: "Em verdade vos digo que ninguém há que tenha abandonado a casa, a mulher, os irmãos, os pais ou os filhos por causa do reino de Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 30, 'que não receba muito mais já neste mundo, e, no século futuro, a vida eterna."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 31, 'Em seguida tomou Jesus aparte os doze, e disse-Ihes: "Eis que vamos para Jerusalém, e será cumprido tudo o que está escrito pelos profetas relativo ao Filho do homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 32, 'Será entregue aos gentios, será escarnecido, ultrajado, cuspido;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 33, 'e, depois de o açoutarem, o matarão, e ressuscitará ao terceiro dia."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 34, 'Eles, porém, nada disto compreenderam; este discurso era para eles obscuro, e não penetravam coisa alguma do que lhes dizia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 35, 'Sucedeu que, aproximando-se eles de Jericó, estava sentado à borda da estrada um cego pedindo esmola.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 36, 'Ouvindo a turba que passava, perguntou que era aquilo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 37, 'Disseram-lhe que era Jesus Nazareno que passava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 38, 'Então ele clamou : "Jesus, Filho de David, tem piedade de mim !"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 39, 'Os que iam adiante repreendiam-no para que se calasse. Porém, ele, cada vez gritava mais: "Filho de David, tem piedade de mim!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 40, 'Jesus, parando, mandou que lho trouxessem. Quando ele chegou, interrogou-o:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 41, '"Que queres que eu te faça?" Ele respondeu: "Senhor, fazei que eu veja."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 42, 'Jesus disse-lhe: "Vê; a tua fé te salvou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 43, 'Imediatamente, viu, e foi-o seguindo, glorificando a Deus. Todo o povo, vendo isto, deu louvor a Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 1, 'Tendo entrado em Jericó, atravessava a cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 2, 'Eis que um homem, chamado Zaqueu, o qual era um chefe dos publicanos, e rico,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 3, 'procurava conhecer de vista Jesus, mas não o podia por causa da multidão, porque era pequeno de estatura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 4, 'Correndo adiante, subiu a um sicómoro para o ver; porque havia de passar por ali.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 5, 'Quando Jesus chegou àquele lugar, levantou os olhos e disse-lhe : "Zaqueu, desce depressa, porque convém que eu fique hoje em tua casa."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 6, 'Ele desceu a toda a pressa, e recebeu-o alegremente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 7, 'Vendo isto, todos murmuravam, dizendo: "Foi hospedar-se em casa de um homem pecador."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 8, 'Entretanto Zaqueu, de pé diante do Senhor, disse-Ihe: "Eis, Senhor, que dou aos pobres metade dos meus bens e, naquilo em que eu tiver defraudado alguém restituir-lhe-ei no quádruplo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 9, 'Jesus disse-lhe: "Hoje entrou a salvação nesta casa, porque este também é filho de Abraão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 10, 'Porque o Filho do homem veio buscar e salvar o que estava perdido."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 11, 'Estando eles a ouvir isto, Jesus acrescentou uma parábola, por estar perto de Jerusalém, e porque julgavam que o reino de Deus se havia de manifestar em breve.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 12, 'Disse pois: "Um homem nobre foi para um país distante tomar posse de um reino, para depois voltar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 13, 'Chamando dez dos seus servos, deu-lhes dez marcos de prata, e disse-lhes: Negociai com eles até eu vir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 14, 'Mas os seus concidadãos aborreciam-no; e enviaram atrás dele deputados encarregados de dizer: Não queremos que este reine sobre nós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 15, 'Quando ele voltou, depois de ter tomado posse do reino, mandou chamar aqueles servos, a quem dera o dinheiro, a fim de saber quanto cada um tinha lucrado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 16, 'Veio o primeiro e disse: Senhor, o teu marco rendeu dez marcos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 17, 'Ele disse-lhe: Está bem, servo bom; porque foste fiel no pouco, serás governador de dez cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 18, 'Veio o segundo e disse: Senhor, o teu marco rendeu cinco marcos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 19, 'Respondeu-lhe: Sê tu também governador de cinco cidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 20, 'Veio depois o outro e disse: Senhor, eis o teu marco que guardei embrulhado num lenço;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 21, 'porque tive medo de ti, que és um homem austero, que tiras donde não puseste, e recolhes o que não semeaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 22, 'Disse-lhe o senhor: Servo mau, pela tua mesma boca te julgo. Sabias que eu sou um homem austero, que tiro donde não pus, e recolho o que não semeei;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 23, 'logo, porque não puseste o meu dinheiro num banco, para que, quando eu viesse, o recebesse com os juros?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 24, 'Depois disse aos que estavam presentes: Tirai-lhe o marco de prata, e dai-o ao que tem dez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 25, 'Eles responderam-Ihe: Senhor, ele já tem dez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 26, 'Pois eu vos digo que a todo aquele que tiver, se lhe dará; mas ao que não tem, será tirado ainda mesmo o que tem. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 27, 'Quanto, porém, àqueles meus inimigos, que não quiseram que eu fosse seu rei, trazei-os aqui, e degolai-os na minha presença.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 28, 'Dito isto, ia Jesus adiante subindo para Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 29, 'Aconteceu que, quando chegou perto de Belfagé e de Betânia junto do monte chamado das Oliveiras, enviou dois dos seus discípulos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 30, 'dizendo: "Ide a essa aldeia, que está fronteira; entrando nela, encontrareis um jumentinho alado, em que nunca montou pessoa alguma; desprendei-o e trazei-o.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 31, 'Se alguém vos perguntar porque o soltais, dir-lhe-eis: Porque o Senhor tem necessidade dele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 32, 'Partiram, pois, os que tinham sido enviados, e encontraram tudo como o Senhor lhes dissera.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 33, 'Quando desprendiam o jumentinho, disseram-lhes os seus donos: "Porque soltais vós esse jumentinho?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 34, 'Eles responderam: "Porque o Senhor tem necessidade dele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 35, 'Levaram-no a Jesus. E, lançando sobre o jumentinho os seus mantos, fizeram-no montar em cima.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 36, 'Á sua passagem, as multidões estendiam os seus mantos no caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 37, 'Quando já ia chegando à descida do monte das Oliveiras, toda a multidão dos seus discípulos começou alegremente a louvar a Deus em altas vozes por todas as maravilhas que tinham visto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 38, 'dizendo: "Bendito o rei que vem em nome do Senhor! (Ps. 117, 26). Paz no céu e gloria nas alturas!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 39, 'Então alguns dos fariseus que se achavam entre o povo, disseram-lhe: "Mestre, repreende os teus discípulos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 40, 'Mas ele respondeu-lhes: "Digo-vos que, se eles se calarem, clamarão as mesmas pedras."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 41, 'Quando chegou perto, ao ver a cidade, chorou sobre ela, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 42, '"Se ao menos neste dia, que te é dado, tu também conhecesses o que te pode trazer a paz!... Mas agora isto está encoberto aos teus olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 43, 'Porque virão para ti dias em que os teus inimigos te cercarão de trincheiras, te sitiarão, te apertarão por todos os lados,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 44, 'derribarão por terra a ti e aos teus filhos, que estão dentro de ti, e não deixarão em ti pedra sobre pedra, porque não conheceste o tempo em que foste visitada."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 45, 'Tendo entrado no templo, começou a expulsar os que vendiam nele,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 46, 'dizendo-lhes: "Está escrito: A minha casa é casa de oração (Is. 56, 7); e vós fizestes dela um covil de ladrões (Je. 7, 11)."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 47, 'Todos os dias ensinava no templo. Mas os príncipes dos sacerdotes, os escribas, e os chefes do povo procuravam perdê-lo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 48, 'porém, não sabiam como proceder, porque todo o povo estava suspenso, quando o ouvia.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 1, 'Num daqueles dias, estando Jesus no templo ensinando o povo e anunciando a boa nova, juntaram-se os príncipes dos sacerdotes e os escribas com os de Jesus, anciães,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 2, 'e falaram-lhe neste termos: "Diz-nos com que direito fazes tu estas coisas, ou quem te deu tal autoridade?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 3, 'Jesus respondeu: "Também eu vos farei uma pergunta. Respondei-me:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 4, 'O baptismo de João era do céu ou dos homens?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 5, 'Mas eles discorriam dentro de si: "Se dissermos: do céu, dirá: Por que razão pois, não creste nele?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 6, 'Se dissermos dos homens, todo o povo nos apedrejará, porque está convencido que João era um profeta."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 7, 'Responderam, pois, que não sabiam donde era.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 8, 'Jesus, disse-lhes: "Nem eu vos direi com que autoridade faço estas coisas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 9, 'Começou a dizer ao povo esta parábola: "Um homem plantou uma vinha, arrendou-a a uns vinhateiros, e ausentou-se para longe durante muito tempo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 10, 'No tempo próprio, enviou um servo aos vinhateiros, para que lhe dessem a sua parte do fruto da vinha. Eles, porém, depois de lhe terem batido, reenviaram-no com as mãos vazias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 11, 'Tornou a enviar outro servo. Mas eles, tendo também batido neste, e carregando-o de afrontas, o despediram sem nada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 12, 'Tornou a enviar ainda terceiro. E eles, ferindo-o, deitaram fora também a este.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 13, 'Disse então o senhor da vinha: Que hei-de fazer? Mandarei meu filho amado; talvez lhe guardarão respeito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 14, 'Mas, quando os vinhateiros o viram, discorreram entre si, dizendo: Este é o herdeiro, matemo-lo, e será nossa a herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 15, 'E, lançando-o fora da vinha, mataram-no. Que lhes fará, pois, o senhor da vinha?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 16, 'Virá e acabará de todo com aqueles vinhateiros, e dará a vinha a outros." Tendo eles ouvido isto, disseram: "Deus tal não permita !"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 17, 'Jesus, olhando para eles, disse: "Pois que quer dizer isto que está escrito: A pedra que os edificadores desprezaram, tornou-se pedra angular? (Ps. 117, 22).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 18, 'Todo o que cair sobre aquela pedra, será quebrado; e sobre quem ela cair, será esmagado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 19, 'Os príncipes dos sacerdotes e os escribas procuravam lançar-lhe as mãos naquela hora, mas temeram o povo. Compreenderam bem que esta parábola tinha sido dita contra eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 20, 'Não o perdendo de vista, mandaram espias que se disfarçassem em homens de bem, para o apanharem no que dizia, a fim de o poderem entregar à autoridade e ao poder do governador.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 21, 'Estes interrogaram-no, dizendo: "Mestre, sabemos que falas e ensinas rectamente, que não fazes acepção de pessoas, mas que ensinas o caminho de Deus com verdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 22, 'É-nos permitido dar o tributo a César ou não ?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 23, 'Jesus, conhecendo a sua astúcia, disse-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 24, '"Mostrai-me um dinheiro. De quem é a imagem e a inscrição que tem ?" Responderam : "De César."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 25, 'Ele disse-lhes: "Dai pois a César o que é de César, e a Deus o que é de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 26, 'Não puderam surpreendê-lo em qualquer palavra diante do povo. Admirados da sua resposta, calaram-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 27, 'Aproximaram-se depois alguns saduceus, que negam a ressurreição, e fizeram-lhe a seguinte pergunta:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 28, '"Mestre, Moisés deixou-nos escrito: Se morrer o irmão de algum, tendo mulher, e não deixar filhos, case-se com ela o seu irmão, para dar descendência ao seu irmão (Dt. 25, 5-6).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 29, 'Ora havia sete irmãos. O primeiro casou, e morreu sem filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 30, 'Casou também o segundo com a viúva, e morreu sem filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 31, 'Casou depois com ela o terceiro. E assim sucessivamente todos os sete, e morreram sem deixar filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 32, 'Morreu enfim também a mulher, depois de todos eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 33, 'Na ressurreição, de qual deles será ela mulher, pois que o foi de todos sete?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 34, 'Jesus disse-lhes: "Os filhos deste século casam e são dados em casamento,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 35, 'mas os que forem julgados dignos do século futuro e da ressurreição dos mortos, nem os homens desposarão mulheres, nem as mulheres homens,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 36, 'porque não poderão jamais morrer; porquanto são semelhantes aos anjos, e são filhos de Deus, visto serem filhos da ressurreição. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 37, 'Que os mortos hajam de ressuscitar, o mostrou também Moisés a propósito da sarça, quando chamou ao Senhor o Deus de Abraão, o Deus de Isaac, o Deus de Jacob (Ex. 3, 6). (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 38, 'Ora Deus não é Deus de mortos, mas de vivos, porque para ele, todos são vivos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 39, 'Alguns dos escribas disseram-lhe: "Mestre, falaste bem"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 40, 'Dali em diante, não se atreveram mais a interrogá-lo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 41, 'Jesus disse-lhes: "Como dizem que o Cristo é filho de David?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 42, 'Quando o mesmo David, no livro dos Salmos (Ps. 109, 1), diz: Disse o Senhor ao meu Senhor; Senta-te à minha direita,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 43, 'até que eu ponha os teus inimigos por escabelo de teus pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 44, 'Se David, pois, lhe chama Senhor, como pode ele ser seu filho?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 45, 'Depois, ouvindo-o todo o povo, Jesus disse aos seus discípulos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 46, '"Guardai-vos dos escribas, que gostam de andar com vestidos compridos, de ser saudados nas praças, de ocupar as primeiras cadeiras nas sinagogas, e os primeiros lugares nos banquetes;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 47, 'que devoram as casas das viúvas, a pretexto de longas orações. Estes receberão uma condenação mais severa." (ver nota)');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 1, 'Levantando Jesus os olhos, viu vários ricos que lançavam as suas oferendas no gazofilácio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 2, 'Viu também uma viúva pobrezinha, que lançava duas pequenas moedas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 3, 'E disse: "Na verdade vos digo que esta pobre viúva lançou mais que todos os outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 4, 'Porque todos esses fizeram a Deus oferta do que lhes sobejava; ela, porém, deu da sua mesma indigência tudo o que tinha para viver."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 5, 'Dizendo alguns, a respeito do templo, que estava ornado de belas pedras e de ricas ofertas, Jesus disse;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 6, '"De tudo isto que vedes, virão dias em que não ficará pedra sobre pedra, que não seja demolida."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 7, 'Então interrogaram-no: "Mestre, quando acontecerão estas coisas, e que sinal haverá, quando estiverem para acontecer?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 8, 'Ele respondeu: "Vede, não vos deixeis enganar; porque muitos virão com o meu nome, dizendo: Sou eu, está próximo o tempo. Não os sigais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 9, 'Quando ouvirdes falar de guerras e de tumultos, não vos assusteis; estas coisas devem suceder primeiro; mas não será logo o fim."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 10, 'Depois disse-lhes: "Levantar-se-á nação contra nação, reino contra reino.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 11, 'Haverá grandes terremotos por várias partes, pestes e fomes; aparecerão coisas espantosas, e extraordinários sinais no céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 12, 'Mas antes de tudo isto, lançar-vos-ão as mãos, e vos perseguirão, entregando-vos nas sinagogas, nas prisões, e vos levarão à presença dos reis e dos governadores, por causa do meu nome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 13, 'Isto vos será ocasião de dardes testemunho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 14, 'Gravai, pois, nos vossos corações o não premeditar como vos haveis de defender,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 15, 'porque eu vos darei uma linguagem e uma sabedoria, à qual não poderão resistir, nem contradizer todos os vossos inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 16, 'Sereis entregues por vossos pais, irmãos, parentes, e amigos e farão morrer muitos de vós;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 17, 'e sereis aborrecidos de todos por causa de meu nome;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 18, 'mas não se perderá um cabelo da vossa cabeça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 19, 'Pela vossa perseverança salvareis as vossas almas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 20, 'Mas quando virdes que Jerusalém é sitiada por exércitos, então sabei que está próxima a sua desolação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 21, 'Os que então estiverem na Judeia, fujam para os montes; os que estiverem no meio da cidade, retirem-se; os que estiverem nos campos, não entrem nela;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 22, 'porque estes são dias de vingança, para que se cumpram todas as coisas que estão escritas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 23, 'Aí das mulheres grávidas, e das que amamentarem naqueles dias! porque haverá grande angústia sobre a terra, e ira contra este povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 24, 'Cairão ao fio da espada, serão levados cativos a todas as nações, e Jerusalém será calcada pelos gentios, até se completarem os tempos dos gentios.1'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 25, 'Haverá sinais no sol, na lua e nas estrelas. Na terra haverá consternação dos povos pela confusão do bramido do mar e das ondas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 26, 'morrendo os homens de susto, na expectação do que virá sobre todo o mundo, porque as virtudes dos céus se abalarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 27, 'Então verão o Filho do homem vir sobre uma nuvem com grande poder e majestade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 28, 'Quando começarem, pois, a suceder estas coisas, erguei-vos, levantai as vossas cabeças, porque está próxima a vossa libertação. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 29, 'Acrescentou esta comparação: Vede a figueira e todas as árvores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 30, 'Quando começam a desabrochar, conheceis que está perto o estio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 31, 'Assim, também, quando virdes que acontecem estas coisas, sabei que está próximo o reino de Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 32, 'Em verdade vos digo que não passará esta geração, sem que todas estas coisas se cumpram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 33, 'Passará o céu e a terra, mas as minhas palavras não passarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 34, 'Velai, pois, sobre vós, para que não suceda que os vossos corações se tornem pesados com as demasias do comer e do beber, com os cuidados desta vida, e para que aquele dia vos não apanhe de improviso;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 35, 'porque ele virá como um laço sobre todos os que habitam sobre a face de toda a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 36, 'Vigiai, pois, orando sem cessar, a fim de que vos torneis dignos de evitar todos estes males que devem suceder, e de aparecer com confiança diante do Filho do homem."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 37, 'Jesus estava de dia ensinando no templo, mas ao anoitecer saía para passar a noite no monte, que se chamava das Oliveiras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 38, 'E todo o povo madrugava para ir ao templo ouvi-lo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 1, 'Aproximava-se a festa dos ázimos, chamada Páscoa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 2, 'Os príncipes dos sacerdotes e os escribas procuravam modo de matar Jesus; porém temiam o povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 3, 'Ora Satanás entrou em Judas, que tinha por sobrenome Iscariotes, um dos doze,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 4, 'o qual foi combinar com os príncipes dos sacerdotes e com os oficiais de que modo lho entregaria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 5, 'Eles ficaram contentes, e combinaram com ele dar-lhe dinheiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 6, 'Judas deu a sua palavra, e buscava ocasião oportuna de lho entregar sem tumulto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 7, 'Chegou o dia dos ázimos, no qual se devia imolar a Páscoa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 8, 'Jesus enviou Pedro e João, dizendo: "Ide, preparai-nos a refeição pascal."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 9, 'Eles perguntaram: "Onde queres que a preparemos?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 10, 'Ele disse-Ihes: "Logo que entrardes na cidade, sair-vos-á ao encontro um homem levando uma bilha de água; segui-o até à casa em que entrar;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 11, 'e direis ao dono da casa: O Mestre manda-te dizer: Onde está o aposento em que hei-de comer a Páscoa com os meus discípulos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 12, 'Ele vos mostrará uma grande sala toda ornada; preparai aí o que for preciso."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 13, 'Indo eles, encontraram tudo como Jesus Ihes dissera; e prepararam a Páscoa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 14, 'Chegada a hora, pôs-se Jesus à mesa com os Apóstolos, e'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 15, 'disse-lhes: "Tenho desejado ardentemente comer convosco esta Páscoa, antes de sofrer,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 16, 'porque vos digo que não mais a comerei, até que ela se cumpra no reino de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 17, 'Tendo tomado o cálice, deu graças, e disse: "Tomai e distribuí-o entre vós,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 18, 'porque vos declaro que não tornarei a beber do fruto da vide, até que chegue o reino de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 19, 'Depois tomou o pão, deu graças, partiu, e deu-lho, dizendo: "Isto é o meu corpo, que é dado por vós; fazei isto em memória de mim. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 20, 'Tomou da mesma sorte o cálice, depois de cear, dizendo: "Este cálice é a nova Aliança em meu sangue, que é derramado por vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 21, 'Entretanto, eis que a mão de quem me há-de entregar está à mesa comigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 22, 'Na verdade, o Filho do homem vai, segundo o que está decretado, mas, ai daquele homem, por quem será entregue!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 23, 'Eles começaram a perguntar entre si qual deles seria o que haveria de fazer tal coisa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 24, 'Levantou-se também entre eles uma contenda sobre qual deles se devia considerar o maior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 25, 'Jesus, porém, disse-lhes: "Os reis das nações dominam sobre elas, e os que têm autoridade sobre elas chamam-se benfeitores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 26, 'Não assim entre vós, mas o que entre vós é o maior, faça-se como mais pequeno, e o que governa, seja como o que serve.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 27, 'Porque, qual é maior, o que está à mesa, ou o que serve? Não é maior o que está sentado à mesa? Pois eu estou no meio de vós como um que serve.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 28, 'Vós sois os que tendes permanecido comigo nas minhas tribulações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 29, 'Por isso eu preparo o reino para vós, como meu Pai o preparou para mim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 30, 'para que comais e bebais à minha mesa, no meu reino, e vos senteis sobre tronos a julgar as doze tribos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 31, 'Simão, Simão, eis que Satanás vos busca com instância para vos joeirar como trigo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 32, 'mas eu roguei por ti, para que a tua fé não desfaleça; e tu, uma vez convertido, conforta os teus irmãos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 33, 'Pedro disse-Ihe: "Senhor, eu estou pronto a ir contigo para a prisão e para a morte."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 34, 'Jesus, porém, disse-lhe: Digo-te, Pedro, que não cantará hoje o galo, sem que tu, por três vezes, me tenhas negado que me conheces." Depois disse-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 35, '"Quando eu vos mandei sem bolsa, sem alforge, sem sandálias, faltou-vos porventura alguma coisa?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 36, 'Eles responderam: "Nada." Disse-Ihes, pois: "Mas agora quem tem bolsa, tome-a, e também alforge, quem não tem espada venda o seu manto, e compre uma. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 37, 'Porque vos digo que é necessário que se cumpra em mim isto que está escrito: Foi posto entre os malfeitores (Is. 53, 12). Porque as coisas que me dizem respeito estão perto do seu cumprimento."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 38, 'Eles responderam; "Senhor, eis aqui duas espadas." Jesus disse-lhes: "Basta." (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 39, 'Tendo saído, foi, segundo o seu costume, para o monte das Oliveiras. Seus discípulos o seguiram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 40, 'Quando chegou àquele lugar, disse-lhes: "Orai, para não cairdes em tentação."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 41, 'Afastou-se deles a distância de um tiro de pedra; e, posto de joelhos, orava,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 42, 'dizendo: "Pai, se é do teu agrado, afasta de mim este cálice; não se faça, contudo, a minha vontade, mas a tua."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 43, 'Então apareceu-lhe um anjo do céu, que o confortava. Posto em agonia orava mais instantemente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 44, 'O seu suor tornou-se como gotas de sangue, que corriam até à terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 45, 'Tendo-se levantado da oração, e indo ter com seus discípulos, encontrou-os adormecidos pela tristeza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 46, 'Disse-lhes: "Porque dormis? Levantai-vos, e orai, para que não entreis em tentação."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 47, 'Estando ele ainda falando, eis que chega um tropel de gente. Aquele que se chamava Judas, um dos doze, vinha à frente. Aproximou-se de Jesus para o abraçar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 48, 'Jesus disse-lhe: "Judas! com um beijo entregas o Filho do homem?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 49, 'Os que estavam com Jesus, vendo o que ia acontecer, disseram-lhe: "Senhor, se os feríssemos à espada?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 50, 'E um deles feriu um servo do Sumo Pontífice, e cortou-lhe a orelha direita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 51, 'Mas Jesus, tomando a palavra, disse: "Deixai, basta." E, tendo-lhe tocado a orelha, o sarou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 52, 'Disse depois Jesus aos príncipes dos sacerdotes, aos oficiais do templo, e aos anciães que tinham vindo contra ele: "Viestes armados de espadas e de varapaus como contra um ladrão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 53, 'Quando eu estava todos os dias convosco no templo, nunca estendestes a mão contra mim; porém, esta é a vossa hora, e o poder das trevas."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 54, 'Prendendo-o, levaram-no a casa do príncipe dos sacerdotes. Pedro seguia-o de longe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 55, 'Tendo acendido fogo no meio do pátio, e, sentando-se em roda, estava também Pedro sentado no meio deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 56, 'Uma criada, vendo-o sentado ao lume, e fixando-o bem, disse: "Este estava também com ele."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 57, 'Mas Pedro o negou, dizendo: "Mulher, eu não o conheço."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 58, 'Daí a pouco, vendo-o outro, disse-lhe: "Tu também és um deles." Pedro disse: " Ó homem, não sou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 59, 'Passado o intervalo quase de uma hora, um outro dizia com insistência: "Certamente que este também estava com ele, pois é galileu."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 60, 'Pedro respondeu: "Ó homem, não sei o que dizes." Imediatamente, quando ele ainda falava, o galo cantou;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 61, 'e, tendo-se voltado, o Senhor olhou para Pedro. Pedro então lembrou-se da palavra que lhe tinha sido dita pelo Senhor: "Antes que o galo cante, me negarás três vezes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 62, 'E, tendo saído para fora, chorou amargamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 63, 'Os homens, que guardavam Jesus, escarneciam dele e feriam-no.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 64, 'Vendaram-lhe os olhos, e interrogavam-no: "Adivinha, quem é que te deu?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 65, 'E proferiam muitas outras injúrias contra ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 66, 'Quando foi dia, juntaram-se os anciães do povo, os príncipes dos sacerdotes, e os escribas. Levaram-no ao seu tribunal, e disseram-lhe: "Se tu és o Cristo, dize-no-lo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 67, 'Ele respondeu-lhes: "Se eu vo-lo disser, não me acreditareis;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 68, 'também se vos fizer qualquer pergunta, não me respondereis, nem me dareis liberdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 69, 'Mas, no futuro, estará sentado o Filho do homem à direita do poder de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 70, 'Então disseram todos: "Logo tu és o Filho de Deus?" Ele respondeu: "Vós o dizeis, eu o sou."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 71, 'Então eles disseram: "Que mais testemunho nos é necessário? Nós mesmos o ouvimos da sua boca."');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 1, 'Levantando-se toda a multidão, levaram-no a Pilatos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 2, 'Começaram a acusá-lo, dizendo: "Encontrámos este homem sublevando a nossa nação, proibindo dar tributo a César, e dizendo que é o Cristo Rei."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 3, 'Pilatos interrogou-o: "Tu és o rei dos Judeus?" Ele, respondendo, disse: "Tu o dizes."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 4, 'Então Pilatos disse aos príncipes dos sacerdotes e ao povo: "Não encontro neste homem crime algum."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 5, 'Porém eles insistiam, cada vez mais, dizendo: "Ele subleva o povo, ensinando por toda a Judeia, desde a Galileia, onde começou, até aqui."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 6, 'Pilatos, ouvindo falar da Galileia, perguntou se aquele homem era galileu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 7, 'Quando soube que era da jurisdição de Herodes, remeteu-o a Herodes, que, naqueles dias, se encontrava também em Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 8, 'Herodes, tendo visto Jesus, teve grande alegria, porque havia muito tempo tinha desejo de o ver, por ter ouvido dele muitas coisas, e esperava ver-lhe fazer algum milagre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 9, 'Fez-lhe muitas perguntas. Mas ele nada lhe respondeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 10, 'Estavam presentes os príncipes dos sacerdotes e os escribas, acusando-o com grande insistência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 11, 'Herodes com os seus guardas desprezou-o, fez escárnio dele, mandando-o vestir com uma vestidura branca, e tornou-o a enviar a Pilatos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 12, 'Naquele dia, ficaram amigos Herodes e Pilatos; porque antes eram inimigos um do outro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 13, 'Pilatos, tendo chamado os príncipes dos sacerdotes, os magistrados e o povo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 14, 'disse-lhes: "Vós apresentaste-me este homem como amotinador do povo; ora, interrogando-o eu diante de vós, não encontrei nele culpa alguma daquelas de que o acusais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 15, 'Nem Herodes tão-pouco, porque no-lo remeteu. Nada lhe foi encontrado que mereça morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 16, 'Por isso soltá-lo-ei depois de castigado."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 17, 'Ora Pilatos era obrigado a soltar-lhes, pela festa (da Páscoa), um preso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 18, 'Mas todo o povo exclamou a uma voz, dizendo : "Faz morrer este, e solta-nos Barrabás;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 19, 'o qual tinha sido preso por causa de uma sedição levantada na cidade, e por homicidio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 20, 'Pilatos, que desejava livrar Jesus, falou-lhes de novo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 21, 'Eles, porém, tornaram a gritar: "Crucifica-o, crucifica-o!"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 22, 'Ele disse-lhes terceira vez: "Mas, que mal fez ele? Não encontro nele causa alguma de morte; castigá-lo-ei, pois, e o soltarei."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 23, 'Eles, porém, insistiam em altos gritos que fosse crucificado ; e os seus clamores iam crescendo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 24, 'Pilatos, pois, decretou que se executasse o que eles pediam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 25, 'Soltou-lhes aquele que tinha sido preso por causa de sedição e de homicídio, como eles reclamavam; e abandonou Jesus ao arbítrio deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 26, 'Quando o iam conduzindo, agarraram um certo Simão Cireneu, que voltava do campo; e puseram a cruz sobre ele, para que a levasse após de Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 27, 'Seguia-o uma grande multidão de povo e de mulheres, que batiam no peito, e o lamentavam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 28, 'Porém Jesus, voltando-se para elas, disse : "Filhas de Jerusalém, não choreis sobre mim, mas chorai sobre vós mesmas e sobre vossos filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 29, 'Porque eis que virá tempo em que se dirá: Ditosas as estéreis, os seios que não geraram, e os peitos que não amamentaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 30, 'Então começarão os homens a dizer aos montes : Caí sobre nós; e aos outeiros : Cobri-nos (Os. 10, 8).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 31, 'Porque, se isto se faz no lenho verde, que se fará no seco?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 32, 'Eram também levados com Jesus outros dois, que eram malfeitores, para serem mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 33, 'Quando chegaram ao lugar que se chama Calvário, ali o crucificaram a ele e aos ladrões, um à direita e outro à esquerda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 34, 'Jesus dizia: "Pai, perdoa-lhes, porque não sabem o que fazem ." Dividindo os seus vestidos, sortearam-nos (Ps. 21, 19).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 35, 'O povo estava observando. Os príncipes dos sacerdotes ( com o povo ) o escarneciam, dizendo: "Salvou os outros, salve-se a si mesmo, se é o Cristo, o escolhido de Deus."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 36, 'Insultavam-no também os soldados, os quais, aproximando-se dele e oferecendo-lhe vinagre,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 37, 'diziam : "Se és o rei dos Judeus, salva-te a ti mesmo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 38, 'Estava também por cima da sua cabeça uma inscrição : Este é o rei dos Judeus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 39, 'Um daqueles ladrões, que estavam pendurados, blasfemava contra ele, dizendo: "Se és o Cristo, salva-te a ti mesmo e a nós."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 40, 'O outro, porém, tomando a palavra, repreendia-o, dizendo: "Nem tu temes a Deus, estando no mesmo suplício?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 41, 'Nós estamos na verdade justamente, porque recebemos o castigo que merecem as nossas acções, mas este não fez nenhum mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 42, 'E dizia a Jesus: "Senhor, lembra-te de mim, quando entrares no teu reino."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 43, 'Jesus disse-lhe: "Em verdade te digo: Hoje estarás comigo no paraíso."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 44, 'Era então quase a hora, sexta, e toda a terra ficou coberta de trevas até à hora nona;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 45, 'escureceu-se o sol, e rasgou-se pelo meio o véu do templo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 46, 'Jesus, exclamando em alta voz, disse: "Pai, nas tuas mãos encomendo o meu espírito (Ps. 30, 6)." Dizendo isto, expirou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 47, 'O centurião, vendo o que tinha acontecido, glorificou a Deus, dizendo : "Na verdade este homem era justo."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 48, 'E toda a multidão que assistia a este espectáculo, e via o que sucedia, retirava-se, batendo no peito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 49, 'Todos os conhecidos de Jesus, e as mulheres que o tinham seguido desde a Galileia, estavam de longe observando estas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 50, 'Então um homem, chamado José, que era membro do Sinédrio, varão bom e justo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 51, 'que não tinha concordado com a determinação dos outros, nem com os seus actos, oriundo de Arimateia, cidade da Judeia, que também esperava o reino de Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 52, 'foi ter com Pilatos, e pediu-lhe o corpo de Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 53, 'Tendo-o descido da cruz, envolveu-o num lençol, e depositou-o num sepulcro aberto na rocha, no qual ainda ninguém tinha sido sepultado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 54, 'Era o dia da Preparação, e o sábado ia começar. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 55, 'Ora as mulheres, que tinham ido da Galileia com Jesus, indo atrás de José, observaram o sepulcro, e de que modo o corpo de Jesus fora nele depositado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 56, 'Voltando, prepararam aromas e bálsamos. No sábado, estiveram em repouso, segundo a lei.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 1, 'No primeiro dia da semana, foram muito cedo ao sepulcro, levando os aromas que tinham preparado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 2, 'Encontraram revolvida a pedra do sepulcro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 3, 'Entrando, não encontraram o corpo do Senhor Jesus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 4, 'Aconteceu que, estando consternadas por isso, eis que apareceram junto delas dois homens com vestidos resplandecentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 5, 'Estando elas medrosas e com os olhos no chão, disseram-lhes: "Porque buscais entre os mortos o que está vivo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 6, 'Ele não está aqui, ressuscitou. Lembrai-vos do que ele vos disse, quando estava na Galileia:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 7, 'Importa que o Filho do homem seja entregue nas mãos de homens pecadores, seja crucificado, ressuscite ao terceiro dia."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 8, 'Então lembraram-se das suas palavras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 9, 'Tendo voltado do sepulcro, contaram todas estas coisas aos onze, e a todos os outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 10, 'As que referiam aos Apóstolos estas coisas eram Maria Madalena, Joana, Maria, mãe de Tiago, e as outras, que estavam com elas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 11, 'Mas estas palavras pareciam-lhes como que um delírio, e não lhes deram crédito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 12, 'Todavia Pedro, levantando-se, correu ao sepulcro. Inclinando-se, viu só os lençóis ( por terra), e retirou-se, admirando consigo mesmo o que sucedera.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 13, 'No mesmo dia, caminhavam dois deles para uma aldeia, chamada Emaús, que estava à distância de Jerusalém sessenta estádios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 14, 'Iam falando um com o outro sobre tudo o que se tinha passado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 15, 'discorrendo entre si, aproximou-se deles o próprio Jesus, e caminhou com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 16, 'Os seus olhos, porém, estavam como que fechados, de modo que não o reconheram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 17, 'Ele disse-Ihes: "Que conversas são essas que ides tendo pelo caminho, porque estais tristes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 18, 'Respondeu um deles, chamado Cléofas: "Só tu és forasteiro em Jerusalém, e não sabes o que ali se tem passado estes dias?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 19, 'Ele disse-lhes: "Que é?" Responderam : "Sobre Jesus Nazareno, que foi um profeta, poderoso em obras e em palavras, diante de Deus e de todo o povo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 20, 'e de que maneira os nossos príncipes dos sacerdotes e os nossos magistrados o entregaram para ser condenado à morte, e o crucificaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 21, 'Ora nós esperávamos que ele fosse o que havia de resgatar Israel; depois de tudo isto, é já hoje o terceiro dia, depois que estas coisas sucederam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 22, 'É bem verdade que algumas mulheres, das que estavam entre nós, nos sobressaltaram, porque, ao amanhecer, foram ao sepulcro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 23, 'e, não tendo encontrado o seu corpo, voltaram dizendo que tinham tido uma aparição de anjos, os quais disseram que ele está vivo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 24, 'Alguns dos nossos foram ao sepulcro e acharam que era assim como as mulheres tinham dito; mas não o encontraram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 25, 'Então Jesus disse-lhes: "Ó estultos e tardos do coração para crer tudo o que anunciaram os profetas'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 26, 'Porventura não era necessário que o Cristo sofresse tais coisas, para entrar na sua glória?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 27, 'Em seguida, começando por Moisés, e discorrendo por todos os profetas, explicava-lhes o que dele se encontrava dito em todas as Escrituras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 28, 'Aproximaram-se da aldeia, para onde caminhavam. Jesus fingiu que ia para mais longe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 29, 'Mas eles o constrangeram, dizendo: "Fica connosco, porque faz-se tarde, e o dia declina." Entrou para ficar com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 30, 'Estando com eles à mesa, tomou o pão, o benzeu, partiu, e lho deu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 31, 'Abriram-se os seus olhos, e reconheceram-no; mas ele desapareceu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 32, 'Disseram então um para o outro: "Não é verdade que nós sentíamos abrasar-se-nos o coração, quando ele nos falava pelo caminho, e nos explicava as Escrituras?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 33, 'Levantando-se na mesma hora, voltaram para Jerusalém. Encontraram juntos os onze, e os que estavam com eles,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 34, 'os quais diziam : "Na verdade o Senhor ressuscitou e apareceu a Simão."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 35, 'E eles contaram também o que lhes tinha acontecido no caminho, e como o tinham reconhecido ao partir o pão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 36, 'Enquanto falavam nisto, apresentou-se Jesus no meio deles, e disse-lhes: "A paz seja convosco."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 37, 'Mas eles, turbados e espantados, julgavam ver algum espirito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 38, 'Jesus disse-lhes: "Porque estais turbados, e que pensamentos são esses que vos sobem aos corações?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 39, 'Olhai para as minhas mãos e pés, porque sou eu mesmo; apalpai, e vede, porque um espírito não tem carne, nem ossos, como vós vedes que eu tenho."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 40, 'Dito isto, mostrou-lhes as mãos e os pés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 41, 'Mas, não crendo eles ainda e estando fora de si com a alegria que sentiam, perguntou-lhes: "Tendes aqui alguma coisa que se coma?"'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 42, 'Eles apresentaram-lhe uma posta de peixe assado e um favo de mel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 43, 'Tendo-os tomado comeu-os à vista deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 44, 'Depois disse-Ihes: "Isto é que eu vos dizia, quando ainda estava convosco, que era necessário que se cumprisse tudo o que de mim estava escrito na lei de Moisés, nos profetas e nos salmos."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 45, 'Então abriu-lhes o entendimento, para compreenderem as Escrituras;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 46, 'e disse-lhes: "Assim está escrito, e assim era necessário que o Cristo padecesse e ressuscitasse dos mortos ao terceiro dia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 47, 'e que em seu nome se pregasse a penitência e a remissão dos pecados a todas as nações, começando por Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 48, 'Vós sois as testemunhas destas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 49, 'Eu vou mandar sobre vós o que meu Pai prometeu. Entretanto permanecei na cidade, até que sejais revestidos da virtude do alto."'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 50, 'Depois levou-os até cerca de Betânia, e levantando as suas mãos, os abençoou,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 51, 'Enquanto os abençoava, separou-se deles, e elevava-se ao céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 52, 'Eles, depois de se haverem prostrado diante dele, voltaram para Jerusalém com grande júbilo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 53, 'e estavam continuamente no templo, louvando a Deus.');
